import { createDoublingModel } from "./spelling-doubling.js";
import type { Grapheme, GraphemeCondition, Phoneme } from "../types.js";
import type { LanguageConfig } from "../config/language.js";
import { VOWEL_LETTERS } from "../utils/letters.js";

/** Fixed phone/structure context at the spelling-selection boundary. */
export interface GraphemeSlot {
  phoneme: Phoneme;
  prevPhoneme?: Phoneme;
  nextPhoneme?: Phoneme;
  index: number;
  total: number;
  position: "onset" | "nucleus" | "coda";
  syllableIndex: number;
  syllableCount: number;
  onsetLength: number;
  nucleusLength: number;
  codaLength: number;
  isCluster: boolean;
  stress?: string;
  /** Syllable position of the previous phone, if any. */
  previousPosition?: "onset" | "nucleus" | "coda";
  /** Written text known to follow this slot (the next part's spelling), if any. */
  nextWritten?: string;
}

/**
 * Per-phoneme spelling state carried left to right through a word. It precedes
 * duplicate cleanup and generic spelling rewrites. The writer and the coverage
 * planner both move it with {@link advanceGraphemePrefix} and
 * {@link rollGraphemePrefixSyllable}, so they always see the same state.
 */
export interface GraphemePrefixState {
  /** Previous phoneme's written form, after doubling. */
  readonly previousForm?: string;
  /** Doublings applied so far in the word. */
  readonly doublingCount: number;
  /** Nucleus grapheme selected in the current syllable ("" before the nucleus). */
  readonly nucleusForm: string;
  /** Nucleus grapheme of the previous syllable ("" in the first syllable). */
  readonly previousNucleusForm: string;
}

export const INITIAL_GRAPHEME_PREFIX: GraphemePrefixState = {
  previousForm: undefined, doublingCount: 0, nucleusForm: "", previousNucleusForm: "",
};

/**
 * The nucleus form doubling reads for a phoneme whose selected grapheme is
 * `selectedForm`: an onset closes the previous syllable's vowel, a nucleus sees
 * itself, and a coda sees its own syllable's nucleus.
 */
export function doublingNucleusForm(state: GraphemePrefixState, position: GraphemeSlot["position"], selectedForm: string): string {
  if (position === "onset") return state.previousNucleusForm;
  return position === "nucleus" ? selectedForm : state.nucleusForm;
}

/** State after a phoneme selects `selectedForm` and is written as `form`. */
export function advanceGraphemePrefix(
  state: GraphemePrefixState,
  position: GraphemeSlot["position"],
  selectedForm: string,
  form: string,
  countIncrement: number,
): GraphemePrefixState {
  return {
    previousForm: form,
    doublingCount: state.doublingCount + countIncrement,
    nucleusForm: position === "nucleus" ? selectedForm : state.nucleusForm,
    previousNucleusForm: state.previousNucleusForm,
  };
}

/** State at the start of the next syllable: the current nucleus becomes the previous one. */
export function rollGraphemePrefixSyllable(state: GraphemePrefixState): GraphemePrefixState {
  return { ...state, previousNucleusForm: state.nucleusForm, nucleusForm: "" };
}

// ---------------------------------------------------------------------------
// Context conditioning
// ---------------------------------------------------------------------------

/**
 * Build category shorthand → Set<string> maps from a phoneme inventory.
 */
export function buildCategorySets(phonemes: Phoneme[]): Map<string, Set<string>> {
  const categories = new Map<string, Set<string>>();
  categories.set("lax-vowel", new Set());
  categories.set("tense-vowel", new Set());
  categories.set("front-vowel", new Set());
  categories.set("back-vowel", new Set());
  categories.set("c-soft-vowel", new Set());
  categories.set("vowel", new Set());
  categories.set("consonant", new Set());

  for (const p of phonemes) {
    const isVowel =
      p.mannerOfArticulation === "highVowel" ||
      p.mannerOfArticulation === "midVowel" ||
      p.mannerOfArticulation === "lowVowel";

    if (isVowel) {
      categories.get("vowel")!.add(p.sound);
      if (p.tense === false) categories.get("lax-vowel")!.add(p.sound);
      if (p.tense === true) categories.get("tense-vowel")!.add(p.sound);
      if (p.placeOfArticulation === "front") categories.get("front-vowel")!.add(p.sound);
      // (Triphthongs removed — /aɪə/ decomposed into diphthong + /ə/.)
      if (p.placeOfArticulation === "back") categories.get("back-vowel")!.add(p.sound);
      // Vowels that cause c-softening: front vowels that typically write as e/i/y.
      // Schwa excluded: it often writes as a/o/u where c should be hard (canal, collect).
      const cSoftSounds = new Set(["i:", "ɪ", "ɛ", "eɪ", "aɪ", "ɜ", "ɚ"]);
      if (cSoftSounds.has(p.sound)) categories.get("c-soft-vowel")!.add(p.sound);
    } else {
      categories.get("consonant")!.add(p.sound);
    }
  }

  return categories;
}

/**
 * Expand a context list (which may contain category shorthands) into a Set of phoneme sounds.
 */
function expandContext(ctx: string[], categories: Map<string, Set<string>>): Set<string> {
  const result = new Set<string>();
  for (const item of ctx) {
    const cat = categories.get(item);
    if (cat) {
      for (const s of cat) result.add(s);
    } else {
      result.add(item);
    }
  }
  return result;
}

// ---------------------------------------------------------------------------
// Pre-expanded conditions (Refactor 4)
// ---------------------------------------------------------------------------

interface PreExpandedCondition {
  leftContext?: Set<string>;
  rightContext?: Set<string>;
  notLeftContext?: Set<string>;
  notRightContext?: Set<string>;
  leftGraphemeContext?: Set<string>;
  notLeftGraphemeContext?: Set<string>;
  notRightGraphemeContext?: Set<string>;
  wordFinal?: boolean;
  wordPosition?: ("initial" | "medial" | "final")[];
  segmentPosition?: ("initial" | "medial" | "final")[];
  syllableShape?: GraphemeCondition["syllableShape"];
}

function mergeSyllableShape(
  aliasShape: GraphemeCondition["syllableShape"],
  explicitShape: GraphemeCondition["syllableShape"],
): GraphemeCondition["syllableShape"] {
  if (!aliasShape && !explicitShape) return undefined;
  return {
    ...(aliasShape ?? {}),
    ...(explicitShape ?? {}),
  };
}

/**
 * Resolve an alias-backed grapheme condition into a plain condition object.
 * Explicit grapheme condition fields override alias-provided defaults.
 */
export function normalizeGraphemeCondition(
  condition: GraphemeCondition | undefined,
  aliases: LanguageConfig["graphemeConditionAliases"] | undefined,
  graphemeForm?: string,
): Omit<GraphemeCondition, "alias"> | undefined {
  if (!condition) return undefined;
  let aliasCondition: Omit<GraphemeCondition, "alias"> | undefined;
  if (condition.alias) {
    aliasCondition = aliases?.[condition.alias];
    if (!aliasCondition) {
      const suffix = graphemeForm ? ` for grapheme "${graphemeForm}"` : "";
      throw new Error(`Unknown grapheme condition alias "${condition.alias}"${suffix}`);
    }
  }

  const { alias, syllableShape: explicitSyllableShape, ...explicitFields } = condition;
  void alias;
  const merged: Omit<GraphemeCondition, "alias"> = {
    ...(aliasCondition ?? {}),
    ...explicitFields,
  };
  merged.syllableShape = mergeSyllableShape(aliasCondition?.syllableShape, explicitSyllableShape);
  if (!merged.syllableShape) delete merged.syllableShape;
  return merged;
}

function preExpandConditions(
  graphemes: Grapheme[],
  categories: Map<string, Set<string>>,
  aliases: LanguageConfig["graphemeConditionAliases"] | undefined,
): Map<Grapheme, PreExpandedCondition> {
  const result = new Map<Grapheme, PreExpandedCondition>();
  for (const g of graphemes) {
    const normalized = normalizeGraphemeCondition(g.condition, aliases, g.form);
    if (!normalized) continue;
    const expanded: PreExpandedCondition = {};
    if (normalized.leftContext) expanded.leftContext = expandContext(normalized.leftContext, categories);
    if (normalized.rightContext) expanded.rightContext = expandContext(normalized.rightContext, categories);
    if (normalized.notLeftContext) expanded.notLeftContext = expandContext(normalized.notLeftContext, categories);
    if (normalized.notRightContext) expanded.notRightContext = expandContext(normalized.notRightContext, categories);
    if (normalized.leftGraphemeContext) expanded.leftGraphemeContext = new Set(normalized.leftGraphemeContext);
    if (normalized.notLeftGraphemeContext) expanded.notLeftGraphemeContext = new Set(normalized.notLeftGraphemeContext);
    if (normalized.notRightGraphemeContext) expanded.notRightGraphemeContext = new Set(normalized.notRightGraphemeContext);
    if (normalized.wordFinal !== undefined) expanded.wordFinal = normalized.wordFinal;
    if (normalized.wordPosition) expanded.wordPosition = normalized.wordPosition;
    if (normalized.segmentPosition) expanded.segmentPosition = normalized.segmentPosition;
    if (normalized.syllableShape) expanded.syllableShape = normalized.syllableShape;
    result.set(g, expanded);
  }
  return result;
}

function checkClusterShapeRequirement(length: number, requirement: "empty" | "nonEmpty" | "any" | undefined): boolean {
  if (!requirement || requirement === "any") return true;
  if (requirement === "empty") return length === 0;
  return length > 0;
}

function checkNucleusLengthRequirement(
  length: number,
  requirement: NonNullable<GraphemeCondition["syllableShape"]>["nucleusLength"],
): boolean {
  if (requirement === undefined) return true;
  if (typeof requirement === "number") return length === requirement;
  if (requirement.min !== undefined && length < requirement.min) return false;
  if (requirement.max !== undefined && length > requirement.max) return false;
  return true;
}

// ---------------------------------------------------------------------------
// Pipeline Step 1: Get candidates
// ---------------------------------------------------------------------------

function getGraphemeCandidates(
  graphemeMaps: LanguageConfig["graphemeMaps"],
  sound: string,
  position: "onset" | "nucleus" | "coda",
): Grapheme[] {
  return graphemeMaps[position].get(sound) ?? [];
}

// ---------------------------------------------------------------------------
// Pipeline Step 2: Filter by context condition
// ---------------------------------------------------------------------------

function meetsPreExpandedCondition(
  condition: PreExpandedCondition | undefined,
  prevPhoneme: Phoneme | undefined,
  nextPhoneme: Phoneme | undefined,
  isStartOfWord: boolean,
  isEndOfWord: boolean,
  totalPhonemes: number,
  phonemeIndex: number,
  prevGraphemeForm?: string,
  onsetLength?: number,
  nucleusLength?: number,
  codaLength?: number,
  nextWritten?: string,
): boolean {
  if (!condition) return true;

  if (condition.wordPosition) {
    let positionMatch = false;
    const isInitial = isStartOfWord;
    const isFinal = isEndOfWord;
    const isMedial = !isInitial && !isFinal;

    for (const pos of condition.wordPosition) {
      if (pos === "initial" && isInitial) positionMatch = true;
      if (pos === "final" && isFinal) positionMatch = true;
      if (pos === "medial" && isMedial) positionMatch = true;
    }
    if (!positionMatch) return false;
  }

  if (condition.segmentPosition) {
    const initial = phonemeIndex === 0;
    const final = phonemeIndex === totalPhonemes - 1;
    if (!condition.segmentPosition.some(position =>
      (position === "initial" && initial) ||
      (position === "final" && final) ||
      (position === "medial" && !initial && !final)
    )) return false;
  }

  if (condition.leftContext) {
    if (!prevPhoneme) return false;
    if (!condition.leftContext.has(prevPhoneme.sound)) return false;
  }

  if (condition.rightContext) {
    if (!nextPhoneme) return false;
    if (!condition.rightContext.has(nextPhoneme.sound)) return false;
  }

  if (condition.notLeftContext) {
    if (prevPhoneme && condition.notLeftContext.has(prevPhoneme.sound)) return false;
  }

  if (condition.notRightContext) {
    if (nextPhoneme && condition.notRightContext.has(nextPhoneme.sound)) return false;
  }

  if (condition.leftGraphemeContext) {
    if (!prevGraphemeForm) return false;
    const lastLetter = prevGraphemeForm[prevGraphemeForm.length - 1];
    if (!condition.leftGraphemeContext.has(lastLetter)) return false;
  }

  if (condition.notLeftGraphemeContext) {
    if (prevGraphemeForm) {
      const lastLetter = prevGraphemeForm[prevGraphemeForm.length - 1];
      if (condition.notLeftGraphemeContext.has(lastLetter)) return false;
    }
  }

  // Unknown (empty) following text cannot violate a right-letter ban.
  if (condition.notRightGraphemeContext && nextWritten) {
    if (condition.notRightGraphemeContext.has(nextWritten[0])) return false;
  }

  if (condition.wordFinal !== undefined) {
    const endsWord = phonemeIndex === totalPhonemes - 1 && !nextWritten;
    if (endsWord !== condition.wordFinal) return false;
  }

  if (condition.syllableShape) {
    if (!checkClusterShapeRequirement(onsetLength ?? 0, condition.syllableShape.onset)) return false;
    if (!checkClusterShapeRequirement(codaLength ?? 0, condition.syllableShape.coda)) return false;
    if (!checkNucleusLengthRequirement(nucleusLength ?? 0, condition.syllableShape.nucleusLength)) return false;
  }

  return true;
}

function filterByCondition(
  candidates: Grapheme[],
  expandedConditions: Map<Grapheme, PreExpandedCondition>,
  prevPhoneme: Phoneme | undefined,
  nextPhoneme: Phoneme | undefined,
  phonemeIndex: number,
  totalPhonemes: number,
  isStartOfWord: boolean,
  isEndOfWord: boolean,
  prevGraphemeForm?: string,
  onsetLength?: number,
  nucleusLength?: number,
  codaLength?: number,
  nextWritten?: string,
): Grapheme[] {
  const filtered = candidates.filter(g =>
    meetsPreExpandedCondition(
      expandedConditions.get(g),
      prevPhoneme,
      nextPhoneme,
      isStartOfWord,
      isEndOfWord,
      totalPhonemes,
      phonemeIndex,
      prevGraphemeForm,
      onsetLength,
      nucleusLength,
      codaLength,
      nextWritten,
    )
  );
  return filtered;
}

// ---------------------------------------------------------------------------
// Pipeline Step 3: Filter by position
// ---------------------------------------------------------------------------

interface SegmentPosition {
  initial: boolean;
  final: boolean;
}

export function positionLabel(initial: boolean, final: boolean): "initial" | "medial" | "final" | "isolated" {
  if (initial && final) return "isolated";
  if (initial) return "initial";
  return final ? "final" : "medial";
}

function positionWeight(
  grapheme: Grapheme,
  firstSyllable: boolean,
  lastSyllable: boolean,
  segment?: SegmentPosition,
): number {
  const atSegment = grapheme.positionScope === "segment" && segment;
  const initial = atSegment ? atSegment.initial : firstSyllable;
  const final = atSegment ? atSegment.final : lastSyllable;
  if (initial && final) {
    if (!atSegment && grapheme.isolatedSyllableWeight !== undefined) return grapheme.isolatedSyllableWeight;
    // Legacy custom configurations must satisfy both edge exclusions.
    return Math.min(grapheme.startWord ?? 1, grapheme.endWord ?? 1);
  }
  if (initial) return grapheme.startWord ?? 1;
  return final ? (grapheme.endWord ?? 1) : (grapheme.midWord ?? 1);
}

export function filterByPosition(
  candidates: Grapheme[],
  isCluster: boolean,
  firstSyllable: boolean,
  lastSyllable: boolean,
  segment?: SegmentPosition,
): Grapheme[] {
  return candidates.filter(grapheme =>
    (!isCluster || grapheme.cluster === undefined || grapheme.cluster > 0) &&
    positionWeight(grapheme, firstSyllable, lastSyllable, segment) > 0
  );
}

function frequencyWeight(
  grapheme: Grapheme,
  firstSyllable: boolean,
  lastSyllable: boolean,
  segment: SegmentPosition,
  position: "onset" | "nucleus" | "coda",
  stress: string | undefined,
  syllableCount: number,
): number {
  let modifier = 1;
  if (stress !== "ˈ" && syllableCount >= 2 && grapheme.form.length > 1) {
    modifier = position === "nucleus"
      ? Math.max(0.02, 0.15 / syllableCount)
      : Math.max(0.15, 0.5 / syllableCount);
  }
  return grapheme.frequency * positionWeight(grapheme, firstSyllable, lastSyllable, segment) * modifier;
}

type GraphemeFallbackReason = "no-conditioned-candidates" | "no-positional-candidates" | "no-positive-weights";

function fallbackReason(conditionedCount: number, positionalCount: number): GraphemeFallbackReason {
  if (conditionedCount === 0) return "no-conditioned-candidates";
  if (positionalCount === 0) return "no-positional-candidates";
  return "no-positive-weights";
}

/** A spelling that reads as a doubled consonant: a configured doubled form of its sound (ck) or a repeated consonant letter (ssi). */
export function isDoubledSpelling(
  grapheme: Pick<Grapheme, "phoneme" | "form">,
  isDirectForm: (sound: string, form: string) => boolean,
): boolean {
  const { phoneme, form } = grapheme;
  return isDirectForm(phoneme, form) ||
    (form.length >= 2 && form[0] === form[1] && !VOWEL_LETTERS.has(form[0].toLowerCase()));
}

/** Drop candidates that `exclude` rejects, unless that would leave none. */
function preferCandidates(
  weights: [Grapheme, number][],
  exclude: (grapheme: Grapheme) => boolean,
): [Grapheme, number][] | undefined {
  const kept = weights.filter(([grapheme]) => !exclude(grapheme));
  return kept.length > 0 ? kept : undefined;
}

export class NoLegalGraphemeError extends Error {}

/** One hard-legality and soft-quota policy, shared by selection and respelling. */
export function createGraphemeResolver(config: LanguageConfig) {
  const graphemeMaps = config.graphemeMaps;
  const doubling = config.doubling;
  for (const grapheme of config.graphemes) {
    const weights = [grapheme.frequency, grapheme.startWord, grapheme.midWord, grapheme.endWord,
      grapheme.onset, grapheme.nucleus, grapheme.coda, grapheme.cluster, grapheme.isolatedSyllableWeight];
    if (weights.some(weight => weight !== undefined && (!Number.isFinite(weight) || weight < 0))) {
      throw new Error(`Invalid grapheme weight for /${grapheme.phoneme}/ → ${grapheme.form}`);
    }
  }
  const expanded = preExpandConditions(config.graphemes, buildCategorySets(config.phonemes), config.graphemeConditionAliases);
  const doublingModel = createDoublingModel(doubling);
  const neverDoubleAfter = new Set<string>(doubling?.enabled ? doubling.neverDoubleAfter ?? [] : []);
  return (slot: GraphemeSlot, prefix: GraphemePrefixState) => {
    const firstSyllable = slot.syllableIndex === 0;
    const lastSyllable = slot.syllableIndex === slot.syllableCount - 1;
    const segment = { initial: slot.index === 0, final: slot.index === slot.total - 1 };
    const candidates = getGraphemeCandidates(graphemeMaps, slot.phoneme.sound, slot.position);
    const ordinary = candidates.filter(grapheme => !grapheme.fallbackOnly);
    const conditionCandidates = (pool: Grapheme[]): Grapheme[] => filterByCondition(
      pool, expanded, slot.prevPhoneme, slot.nextPhoneme, slot.index, slot.total,
      firstSyllable, lastSyllable, prefix.previousForm,
      slot.onsetLength, slot.nucleusLength, slot.codaLength, slot.nextWritten,
    );
    const positionCandidates = (pool: Grapheme[]): Grapheme[] =>
      filterByPosition(pool, slot.isCluster, firstSyllable, lastSyllable, segment);
    const positiveWeights = (pool: Grapheme[]): [Grapheme, number][] => pool
      .map((grapheme): [Grapheme, number] => [grapheme, frequencyWeight(
        grapheme, firstSyllable, lastSyllable, segment, slot.position, slot.stress, slot.syllableCount,
      )])
      .filter(([, weight]) => weight > 0 && Number.isFinite(weight));
    const conditioned = conditionCandidates(ordinary);
    const positional = positionCandidates(conditioned);
    let weights = positiveWeights(positional);
    const positiveCount = weights.length;
    let fallback: GraphemeFallbackReason | undefined;
    if (weights.length === 0) {
      fallback = fallbackReason(conditioned.length, positional.length);
      weights = positiveWeights(positionCandidates(conditionCandidates(
        candidates.filter(grapheme => grapheme.fallbackOnly),
      )));
      if (weights.length === 0) {
        throw new NoLegalGraphemeError(`No legal grapheme for /${slot.phoneme.sound}/ at segment ${slot.index} ` +
          `(${slot.position}, syllable ${slot.syllableIndex}; ${fallback})`);
      }
    }
    const quotaFull = doublingModel.hasDirectForms && prefix.doublingCount >= (doubling?.maxPerWord ?? Infinity);
    // A consonant written directly after a never-double-after nucleus (ea).
    const afterUndoubledNucleus = slot.position !== "nucleus" && slot.previousPosition === "nucleus" &&
      prefix.previousForm !== undefined && neverDoubleAfter.has(prefix.previousForm);
    let preferred = weights;
    let preferenceRelaxed: "doubling-quota" | "never-double-after" | undefined;
    if (quotaFull) {
      const kept = preferCandidates(preferred, g => doublingModel.isDirectForm(g.phoneme, g.form));
      if (kept) preferred = kept; else preferenceRelaxed = "doubling-quota";
    }
    if (afterUndoubledNucleus) {
      const kept = preferCandidates(preferred, g => isDoubledSpelling(g, doublingModel.isDirectForm));
      if (kept) preferred = kept; else preferenceRelaxed ??= "never-double-after";
    }
    return {
      candidates, ordinary, conditioned, positional, positiveCount, fallback, preferenceRelaxed,
      weights: preferred,
    };
  };
}

import type { LanguageConfig } from "../config/language.js";
import { sonorityClass } from "../config/language.js";
import type { Phoneme } from "../types.js";

export type SspViolation = "rule1" | "rule2" | "rule3" | "multi";

function mannerGroup(p: Phoneme): string {
  const m = p.mannerOfArticulation;
  if (m === "sibilant") return "fricative";
  if (m === "lateralApproximant") return "liquid";
  return m;
}

function isCoronal(p: Phoneme): boolean {
  const place = p.placeOfArticulation;
  return place === "alveolar" || place === "postalveolar" || place === "dental";
}

function placeGroup(p: Phoneme): string {
  const place = p.placeOfArticulation;
  if (place === "bilabial" || place === "labiodental" || place === "labial-velar") return "labial";
  if (place === "dental" || place === "alveolar" || place === "postalveolar") return "coronal";
  if (place === "palatal" || place === "velar") return "dorsal";
  return place;
}

function isSspExceptionSound(sound: string): boolean {
  return sound === "s";
}

export function hasRisingCodaTowardBoundary(coda: Phoneme[], config: LanguageConfig): boolean {
  if (coda.length < 2) return false;
  for (let i = 0; i < coda.length - 1; i++) {
    if (sonorityClass(coda[i], config) < sonorityClass(coda[i + 1], config)) {
      return true;
    }
  }
  return false;
}

function getSspViolations(
  coda: Phoneme[],
  onset: Phoneme[],
  config: LanguageConfig,
): { rule1: boolean; rule2: boolean; rule3: boolean } {
  if (coda.length === 0 || onset.length === 0) {
    return { rule1: false, rule2: false, rule3: false };
  }

  const totalLen = coda.length + onset.length;
  if (totalLen <= 2) {
    return { rule1: false, rule2: false, rule3: false };
  }

  const codaEnd = sonorityClass(coda[coda.length - 1], config);
  const onsetStart = sonorityClass(onset[0], config);

  const rule1 = hasRisingCodaTowardBoundary(coda, config);
  const rule2 = codaEnd === onsetStart &&
    !isSspExceptionSound(coda[coda.length - 1].sound) &&
    !isSspExceptionSound(onset[0].sound);
  const rule3 = onsetStart > codaEnd && !isSspExceptionSound(onset[0].sound);

  return { rule1, rule2, rule3 };
}

export function classifySspViolation(
  coda: Phoneme[],
  onset: Phoneme[],
  config: LanguageConfig,
): SspViolation | null {
  const { rule1, rule2, rule3 } = getSspViolations(coda, onset, config);
  const count = (rule1 ? 1 : 0) + (rule2 ? 1 : 0) + (rule3 ? 1 : 0);
  if (count === 0) return null;
  if (count > 1) return "multi";
  if (rule1) return "rule1";
  if (rule2) return "rule2";
  return "rule3";
}

function isJunctionSonorityValid(
  coda: Phoneme[],
  onset: Phoneme[],
  config: LanguageConfig,
): boolean {
  if (coda.length === 0 || onset.length === 0) return true;

  const totalLen = coda.length + onset.length;
  if (totalLen <= 2) return true;

  // Onset must rise (not fall) internally, with the /s/ exception.
  for (let i = 0; i < onset.length - 1; i++) {
    const left = sonorityClass(onset[i], config);
    const right = sonorityClass(onset[i + 1], config);
    if (left > right && !isSspExceptionSound(onset[i].sound) && !isSspExceptionSound(onset[i + 1].sound)) {
      return false;
    }
  }

  const { rule1, rule2, rule3 } = getSspViolations(coda, onset, config);
  return !(rule1 || rule2 || rule3);
}

function isJunctionValid(C1: Phoneme, C2: Phoneme, onsetCluster: Phoneme[]): boolean {
  // F1: identical phonemes
  if (C1.sound === C2.sound) return false;

  // F2: same mannerGroup AND same exact place of articulation
  if (mannerGroup(C1) === mannerGroup(C2) && C1.placeOfArticulation === C2.placeOfArticulation) return false;

  // F3: stop+stop where neither is coronal
  if (mannerGroup(C1) === "stop" && mannerGroup(C2) === "stop" && !isCoronal(C1) && !isCoronal(C2)) return false;

  // F4: stop+stop voicing disagreement
  if (mannerGroup(C1) === "stop" && mannerGroup(C2) === "stop" && C1.voiced !== C2.voiced) return false;

  // P1: s-exception
  if (C1.sound === "s") return true;
  if (C2.sound === "s" && onsetCluster.length >= 2 && ["t", "p", "k"].includes(onsetCluster[1]?.sound)) return true;
  if (onsetCluster.length >= 2 && onsetCluster[0].sound === "s" && ["t", "p", "k"].includes(onsetCluster[1].sound)) return true;

  // P2: coronal onset
  if (isCoronal(C2)) return true;

  // P3: homorganic nasal+stop
  if (mannerGroup(C1) === "nasal" && mannerGroup(C2) === "stop" && placeGroup(C1) === placeGroup(C2)) return true;

  // P4: manner change
  if (mannerGroup(C1) !== mannerGroup(C2)) return true;

  // P5: place change
  if (placeGroup(C1) !== placeGroup(C2)) return true;

  return false;
}

export function validateJunction(
  coda: Phoneme[],
  onset: Phoneme[],
  config: LanguageConfig,
): boolean {
  if (coda.length === 0 || onset.length === 0) return true;

  const C1 = coda[coda.length - 1];
  const C2 = onset[0];
  if (!isJunctionValid(C1, C2, onset)) return false;
  if (!isJunctionSonorityValid(coda, onset, config)) return false;
  return true;
}

export interface PhonemeTargetBounds {
  minRoot: number;
  maxRoot: number;
}

export interface AttemptScore {
  phonemeDistance: number;
  letterPenalty: number;
  total: number;
}

export interface AcceptanceCriteria {
  /** Attempts before near-target letter lengths can be accepted. */
  warmupAttempts: number;
  /** Largest letter penalty accepted after the warmup. */
  relaxedLetterPenalty: number;
}

export interface AttemptAssessment {
  /** null means the attempt was rejected. */
  acceptedBy: "exact" | "relaxed" | null;
  /** Conditions that rejected the attempt; several can fail at once. */
  failed: { phonemeTarget: boolean; letterLength: boolean; warmup: boolean };
}

function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(value, max));
}

export function computePhonemeTargetBounds(
  forcedRootSyllableCount: number | undefined,
  maxOnsetLength: number,
  maxCodaLength: number,
): PhonemeTargetBounds {
  const minRoot = forcedRootSyllableCount ?? 1;
  const maxRoot = forcedRootSyllableCount
    ? forcedRootSyllableCount + forcedRootSyllableCount * (maxOnsetLength + maxCodaLength) + 1
    : Infinity;
  return { minRoot, maxRoot };
}

/** The sampled target belongs to the root; affix costs do not enter it. */
export function resolveRootPhonemeTarget(sampledRootTarget: number, bounds: PhonemeTargetBounds): number {
  return clamp(sampledRootTarget, bounds.minRoot, bounds.maxRoot);
}

export function resolveLetterLengthBounds(
  targets: Record<number, [number, number, number, number]> | undefined,
  syllableCount: number,
): [number, number, number, number] | null {
  if (!targets) return null;
  if (targets[syllableCount]) return targets[syllableCount];
  const keys = Object.keys(targets).map(Number).filter(Number.isFinite).sort((a, b) => a - b);
  if (keys.length === 0) return null;
  if (syllableCount <= keys[0]) return targets[keys[0]];
  if (syllableCount >= keys[keys.length - 1]) return targets[keys[keys.length - 1]];
  let nearest = keys[0];
  let nearestDist = Math.abs(syllableCount - nearest);
  for (const key of keys.slice(1)) {
    const dist = Math.abs(syllableCount - key);
    if (dist < nearestDist) {
      nearest = key;
      nearestDist = dist;
    }
  }
  return targets[nearest];
}

export function scoreLetterLength(
  letterLength: number,
  syllableCount: number,
  targets: Record<number, [number, number, number, number]> | undefined,
): number {
  const bounds = resolveLetterLengthBounds(targets, syllableCount);
  if (!bounds) return 0;
  const [min, peakMin, peakMax, max] = bounds;
  if (letterLength >= peakMin && letterLength <= peakMax) return 0;
  if (letterLength >= min && letterLength <= max) {
    const edgeDistance = letterLength < peakMin ? peakMin - letterLength : letterLength - peakMax;
    return edgeDistance * 0.5;
  }
  const outsideDistance = letterLength < min ? min - letterLength : letterLength - max;
  return 1 + outsideDistance;
}

/** The phoneme part of an attempt's score; letter penalties only add to it. */
function phonemeScore(phonemeDistance: number): number {
  return phonemeDistance * 2;
}

export function scoreGenerationAttempt(
  generatedPhonemes: number,
  targetPhonemes: number,
  generatedLetters: number,
  generatedSyllables: number,
  letterTargets: Record<number, [number, number, number, number]> | undefined,
): AttemptScore {
  const phonemeDistance = Math.abs(generatedPhonemes - targetPhonemes);
  const letterPenalty = scoreLetterLength(generatedLetters, generatedSyllables, letterTargets);
  return {
    phonemeDistance,
    letterPenalty,
    total: phonemeScore(phonemeDistance) + letterPenalty,
  };
}

/**
 * True when an attempt's outcome is already decided by its phoneme count: it
 * misses the target, so no acceptance criterion can pass, and its total score
 * cannot fall below the best attempt so far, so it cannot become the fallback.
 * Such an attempt need not be spelled.
 */
export function isDecidedRejection(phonemeDistance: number, bestScore: number): boolean {
  return phonemeDistance > 0 && phonemeScore(phonemeDistance) >= bestScore;
}

/**
 * Decide whether an attempt is accepted. An exact match is always accepted;
 * after the warmup, a matching phoneme count with a small letter penalty is too.
 */
export function assessAttempt(
  score: AttemptScore,
  attemptIndex: number,
  criteria: AcceptanceCriteria,
): AttemptAssessment {
  // Preserve the original positive acceptance checks: NaN must not be accepted
  // merely because it fails neither a greater-than nor a warmup comparison.
  const exact = score.phonemeDistance === 0 && score.letterPenalty === 0;
  const relaxed = attemptIndex >= criteria.warmupAttempts
    && score.phonemeDistance === 0 && score.letterPenalty <= criteria.relaxedLetterPenalty;
  const failed = {
    phonemeTarget: score.phonemeDistance !== 0,
    letterLength: !(score.letterPenalty <= criteria.relaxedLetterPenalty),
    warmup: attemptIndex < criteria.warmupAttempts && score.letterPenalty !== 0,
  };
  return { acceptedBy: exact ? "exact" : relaxed ? "relaxed" : null, failed };
}

import type { Phoneme, Syllable } from "../types.js";

/** Copy all scalar fields and explicitly detach structured phoneme metadata. */
export function clonePhoneme(phoneme: Phoneme): Phoneme {
  const copy = { ...phoneme };
  if (phoneme.nuclearQuantity) copy.nuclearQuantity = { ...phoneme.nuclearQuantity };
  return copy;
}

/** Independent structures for lexical composition and surface realization. */
export function cloneSyllables(syllables: Syllable[]): Syllable[] {
  return syllables.map(syllable => ({
    onset: syllable.onset.map(clonePhoneme),
    nucleus: syllable.nucleus.map(clonePhoneme),
    coda: syllable.coda.map(clonePhoneme),
    stress: syllable.stress,
  }));
}

import { Phoneme, Syllable, WordGenerationContext } from "../../types.js";
import { Affix, AllomorphVariant, AffixSyllable, BoundaryTransform, MorphophonemicRule, PhonologicalCondition, defaultFallbackBridgeOnsets } from "../../config/language.js";
import getWeightedOption from "../../utils/getWeightedOption.js";
import type { MorphologyPlan } from "./plan.js";
import { snapshotAffixForm, snapshotWrittenParts } from "./realization.js";
import type { MorphologyResult, MorphologyWrittenPart, ResolvedAffix } from "./realization.js";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface GeneratorRuntime {
  config: {
    morphology?: import("../../config/language.js").MorphologyConfig;
    phonemes: Phoneme[];
    pronunciation?: import("../../config/language.js").PronunciationConfig;
  };
}

function getBoundaryFallbackBridges(rt: GeneratorRuntime): [string, number][] {
  return rt.config.morphology?.boundaryPolicy?.fallbackBridgeOnsets ?? defaultFallbackBridgeOnsets();
}

function canApplyPrefixRootFallback(rt: GeneratorRuntime): boolean {
  return rt.config.morphology?.boundaryPolicy?.enablePrefixRootFallback ?? true;
}

function canApplyRootSuffixFallback(rt: GeneratorRuntime): boolean {
  return rt.config.morphology?.boundaryPolicy?.enableRootSuffixFallback ?? true;
}

function pickBoundaryBridge(rt: GeneratorRuntime, context: WordGenerationContext): Phoneme | undefined {
  const options: [Phoneme, number][] = getBoundaryFallbackBridges(rt)
    .map(([sound, weight]) => [rt.config.phonemes.find(p => p.sound === sound), weight] as const)
    .filter(([phoneme, weight]) => !!phoneme && weight > 0)
    .map(([phoneme, weight]) => [phoneme!, weight]);
  if (options.length === 0) return undefined;
  return getWeightedOption(options, context.rand);
}

function realizeBoundaryHiatus(
  rt: GeneratorRuntime,
  context: WordGenerationContext,
  left: Syllable,
  right: Syllable,
  boundary: "prefix-root" | "root-suffix",
  rightSyllableIndex: number,
  fallbackEnabled: boolean,
): void {
  if (left.coda.length > 0 || right.onset.length > 0) return;
  const bridge = fallbackEnabled ? pickBoundaryBridge(rt, context) : undefined;
  if (bridge) {
    right.onset.unshift(bridge);
    context.trace?.recordStructural({
      event: boundary === "prefix-root" ? "morphPrefixHiatusFallback" : "morphSuffixHiatusFallback",
      inserted: bridge.sound,
      syllableIndex: rightSyllableIndex,
    });
  }
  if (left.nucleus.length > 0 && right.nucleus.length > 0) {
    context.trace?.recordStructural({
      event: "morphHiatusDecision",
      boundary,
      leftSyllableIndex: rightSyllableIndex - 1,
      rightSyllableIndex,
      leftNucleus: left.nucleus.map(phone => phone.sound),
      rightNucleus: right.nucleus.map(phone => phone.sound),
      fallbackEnabled,
      outcome: bridge ? "inserted" : fallbackEnabled ? "no-bridge-candidate" : "preserved",
      inserted: bridge?.sound,
    });
  }
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function getLastPhoneme(context: WordGenerationContext): Phoneme | undefined {
  const syllables = context.word.syllables;
  for (let i = syllables.length - 1; i >= 0; i--) {
    const syl = syllables[i];
    if (syl.coda.length > 0) return syl.coda[syl.coda.length - 1];
    if (syl.nucleus.length > 0) return syl.nucleus[syl.nucleus.length - 1];
    if (syl.onset.length > 0) return syl.onset[syl.onset.length - 1];
  }
  return undefined;
}

function getFirstPhoneme(context: WordGenerationContext): Phoneme | undefined {
  const syllables = context.word.syllables;
  for (let i = 0; i < syllables.length; i++) {
    const syl = syllables[i];
    if (syl.onset.length > 0) return syl.onset[0];
    if (syl.nucleus.length > 0) return syl.nucleus[0];
    if (syl.coda.length > 0) return syl.coda[0];
  }
  return undefined;
}

type BoundarySegment = "onset" | "nucleus" | "coda";

interface BoundarySegmentRef {
  syllableIndex: number;
  segment: BoundarySegment;
  index: number;
  phoneme: Phoneme;
}

function getBoundarySegmentRef(
  syllables: Syllable[],
  isPrefix: boolean,
  target: MorphophonemicRule["target"] = "edge",
): BoundarySegmentRef | undefined {
  if (syllables.length === 0) return undefined;

  if (target === "nucleus") {
    const syllableIndex = isPrefix ? 0 : syllables.length - 1;
    const syllable = syllables[syllableIndex];
    if (syllable.nucleus.length === 0) return undefined;
    const index = isPrefix ? 0 : syllable.nucleus.length - 1;
    return {
      syllableIndex,
      segment: "nucleus",
      index,
      phoneme: syllable.nucleus[index],
    };
  }

  if (isPrefix) {
    for (let i = 0; i < syllables.length; i++) {
      const syl = syllables[i];
      if (syl.onset.length > 0) {
        return { syllableIndex: i, segment: "onset", index: 0, phoneme: syl.onset[0] };
      }
      if (syl.nucleus.length > 0) {
        return { syllableIndex: i, segment: "nucleus", index: 0, phoneme: syl.nucleus[0] };
      }
      if (syl.coda.length > 0) {
        return { syllableIndex: i, segment: "coda", index: 0, phoneme: syl.coda[0] };
      }
    }
    return undefined;
  }

  for (let i = syllables.length - 1; i >= 0; i--) {
    const syl = syllables[i];
    if (syl.coda.length > 0) {
      const idx = syl.coda.length - 1;
      return { syllableIndex: i, segment: "coda", index: idx, phoneme: syl.coda[idx] };
    }
    if (syl.nucleus.length > 0) {
      const idx = syl.nucleus.length - 1;
      return { syllableIndex: i, segment: "nucleus", index: idx, phoneme: syl.nucleus[idx] };
    }
    if (syl.onset.length > 0) {
      const idx = syl.onset.length - 1;
      return { syllableIndex: i, segment: "onset", index: idx, phoneme: syl.onset[idx] };
    }
  }
  return undefined;
}

// ---------------------------------------------------------------------------
// Config-driven boundary transforms
// ---------------------------------------------------------------------------

export function applyBoundaryTransforms(rootWritten: string, transforms: BoundaryTransform[]): string {
  const fired = new Set<string>();
  let result = rootWritten;
  for (const t of transforms) {
    if (t.blockedBy && t.blockedBy.some(name => fired.has(name))) continue;
    if (t.match.test(result)) {
      result = result.replace(t.match, t.replace);
      fired.add(t.name);
    }
  }
  return result;
}

// ---------------------------------------------------------------------------
// Config-driven phonological condition matching
// ---------------------------------------------------------------------------

export function matchesPhonologicalCondition(
  condition: PhonologicalCondition,
  phoneme: Phoneme,
  isPrefix: boolean,
): boolean {
  if (condition.position === "preceding" && isPrefix) return false;
  if (condition.position === "following" && !isPrefix) return false;
  if (condition.sounds && !condition.sounds.includes(phoneme.sound)) return false;
  if (condition.voiced !== undefined && phoneme.voiced !== condition.voiced) return false;
  if (condition.manner && !condition.manner.includes(phoneme.mannerOfArticulation)) return false;
  if (condition.place && !condition.place.includes(phoneme.placeOfArticulation)) return false;
  return true;
}

// ---------------------------------------------------------------------------
// Allomorph resolution
// ---------------------------------------------------------------------------

function allomorphSpecificity(variant: AllomorphVariant): number {
  return (variant.phonologicalCondition.manner || variant.phonologicalCondition.place) ? 0 : 1;
}

function resolveAllomorph(
  affix: Affix,
  phoneme: Phoneme | undefined,
  isPrefix: boolean,
): ResolvedAffix {
  // Sort by specificity: conditions with manner/place constraints before voiced-only
  const selected = phoneme ? affix.allomorphs
    ?.map((variant, index) => ({ variant, index }))
    .sort((a, b) => allomorphSpecificity(a.variant) - allomorphSpecificity(b.variant))
    .find(({ variant }) => matchesPhonologicalCondition(variant.phonologicalCondition, phoneme, isPrefix)) : undefined;
  const form = selected ? { ...selected.variant, written: selected.variant.written ?? affix.written } : affix;
  return {
    planned: snapshotAffixForm(affix),
    resolved: snapshotAffixForm(form),
    allomorphIndex: selected?.index ?? null,
    boundaryPhoneme: phoneme ? {
      sound: phoneme.sound,
      voiced: phoneme.voiced,
      mannerOfArticulation: phoneme.mannerOfArticulation,
      placeOfArticulation: phoneme.placeOfArticulation,
    } : undefined,
  };
}

// ---------------------------------------------------------------------------
// AffixSyllable -> Syllable conversion
// ---------------------------------------------------------------------------

/** Cached phoneme-by-sound map, keyed by inventory identity (reference). */
let _cachedInventory: Phoneme[] | undefined;
let _cachedPhonemeMap: Map<string, Phoneme> | undefined;

function getPhonemeMap(inventory: Phoneme[]): Map<string, Phoneme> {
  if (_cachedInventory === inventory && _cachedPhonemeMap) return _cachedPhonemeMap;
  const map = new Map<string, Phoneme>();
  for (const p of inventory) map.set(p.sound, p);
  _cachedInventory = inventory;
  _cachedPhonemeMap = map;
  return map;
}

function affixSyllablesToSyllables(templates: AffixSyllable[], inventory: Phoneme[]): Syllable[] {
  const phonemeMap = getPhonemeMap(inventory);

  function resolve(sound: string): Phoneme {
    const p = phonemeMap.get(sound);
    if (!p) {
      return {
        sound, voiced: true,
        mannerOfArticulation: "midVowel" as const,
        placeOfArticulation: "central" as const,
        startWord: 1, midWord: 1, endWord: 1,
      };
    }
    return p;
  }

  return templates.map(t => ({
    onset: t.onset.map(resolve),
    nucleus: t.nucleus.map(resolve),
    coda: t.coda.map(resolve),
    stress: undefined,
  }));
}

// ---------------------------------------------------------------------------
// Stress adjustment
// ---------------------------------------------------------------------------

function adjustStress(
  syllables: Syllable[],
  stressEffect: Affix["stressEffect"],
  affixSyllableIndices: number[],
  isPrefix: boolean,
): void {
  if (stressEffect === "none" || affixSyllableIndices.length === 0) return;

  if (stressEffect === "primary") {
    for (const syl of syllables) {
      if (syl.stress === "\u02C8") syl.stress = "\u02CC";
    }
    syllables[affixSyllableIndices[0]].stress = "\u02C8";
  } else if (stressEffect === "secondary") {
    syllables[affixSyllableIndices[0]].stress = "\u02CC";
  } else if (stressEffect === "attract-preceding" && !isPrefix) {
    const firstAffixIdx = affixSyllableIndices[0];
    if (firstAffixIdx > 0) {
      for (const syl of syllables) {
        if (syl.stress === "\u02C8") syl.stress = "\u02CC";
      }
      syllables[firstAffixIdx - 1].stress = "\u02C8";
    }
  }
}

interface FiredMorphophonemicRule {
  rule: string;
  affix: string;
  boundary: "prefix-root" | "root-suffix";
  soundBefore?: string;
  soundAfter?: string;
  writtenBefore?: string;
  writtenAfter?: string;
}

interface PreparedMorphophonemicRule {
  rule: MorphophonemicRule;
  event: FiredMorphophonemicRule;
}

/** Resolved attachment retained between lexical assembly and spelling. */
export interface PreparedMorphology {
  plan: MorphologyPlan;
  prefix?: ResolvedAffix;
  suffix?: ResolvedAffix;
  prefixWritten: string;
  suffixWritten: string;
  rootSyllableStart: number;
  rules: PreparedMorphophonemicRule[];
}

function prepareMorphophonemicRules(
  rootSyllables: Syllable[],
  affix: Affix,
  isPrefix: boolean,
  resolvePhoneme: (sound: string) => Phoneme,
): PreparedMorphophonemicRule[] {
  if (!affix.morphophonemicRules || affix.morphophonemicRules.length === 0) {
    return [];
  }

  const sortedRules = [...affix.morphophonemicRules].sort(
    (a, b) => (a.priority ?? 100) - (b.priority ?? 100),
  );
  const prepared: PreparedMorphophonemicRule[] = [];

  for (const rule of sortedRules) {
    const boundaryRef = getBoundarySegmentRef(rootSyllables, isPrefix, rule.target ?? "edge");
    if (!boundaryRef) continue;
    if (
      rule.phonologicalCondition
      && !matchesPhonologicalCondition(rule.phonologicalCondition, boundaryRef.phoneme, isPrefix)
    ) {
      continue;
    }

    const event: FiredMorphophonemicRule = {
      rule: rule.name,
      affix: affix.written,
      boundary: isPrefix ? "prefix-root" : "root-suffix",
    };

    if (rule.replaceSound && rule.replaceSound !== boundaryRef.phoneme.sound) {
      const next = resolvePhoneme(rule.replaceSound);
      rootSyllables[boundaryRef.syllableIndex][boundaryRef.segment][boundaryRef.index] = next;
      event.soundBefore = boundaryRef.phoneme.sound;
      event.soundAfter = next.sound;
    }

    prepared.push({ rule, event });
  }

  return prepared;
}

// ---------------------------------------------------------------------------
// Main API
// ---------------------------------------------------------------------------

export function prepareMorphology(
  rt: GeneratorRuntime,
  context: WordGenerationContext,
  plan: MorphologyPlan,
): PreparedMorphology | undefined {
  if (plan.template === "bare") return undefined;

  const config = rt.config;
  const syllables = context.word.syllables;

  let prefix: ResolvedAffix | undefined;
  let suffix: ResolvedAffix | undefined;

  if (plan.prefix) {
    const firstPhoneme = getFirstPhoneme(context);
    prefix = resolveAllomorph(plan.prefix, firstPhoneme, true);
  }

  if (plan.suffix) {
    const lastPhoneme = getLastPhoneme(context);
    suffix = resolveAllomorph(plan.suffix, lastPhoneme, false);
  }
  const prefixVariant = prefix?.resolved;
  const suffixVariant = suffix?.resolved;

  const inventory = config.phonemes;
  const phonemeMap = getPhonemeMap(inventory);

  function resolvePhoneme(sound: string): Phoneme {
    return phonemeMap.get(sound) ?? {
      sound, voiced: true,
      mannerOfArticulation: "midVowel" as const,
      placeOfArticulation: "central" as const,
      startWord: 1, midWord: 1, endWord: 1,
    };
  }

  const rules: PreparedMorphophonemicRule[] = [];
  if (plan.prefix && prefixVariant) {
    rules.push(...prepareMorphophonemicRules(
      syllables,
      plan.prefix,
      true,
      resolvePhoneme,
    ));
  }
  if (plan.suffix && suffixVariant) {
    rules.push(...prepareMorphophonemicRules(
      syllables,
      plan.suffix,
      false,
      resolvePhoneme,
    ));
  }

  const prefixWritten = prefixVariant?.written ?? "";
  const suffixWritten = suffixVariant?.written ?? "";

  const prefixSyllables = prefixVariant
    ? (prefixVariant.syllables !== undefined && prefixVariant.syllables.length > 0
      ? affixSyllablesToSyllables(prefixVariant.syllables, inventory)
      : [])
    : [];
  const suffixSyllables = suffixVariant
    ? (suffixVariant.syllables !== undefined && suffixVariant.syllables.length > 0
      ? affixSyllablesToSyllables(suffixVariant.syllables, inventory)
      : [])
    : [];

  // Handle zero-syllable affixes: append phonemes directly to root coda/onset
  if (suffixVariant && suffixVariant.syllableCount === 0 && suffixSyllables.length === 0 && suffixVariant.phonemes.length > 0) {
    const lastSyl = syllables[syllables.length - 1];
    for (const s of suffixVariant.phonemes) {
      lastSyl.coda.push(resolvePhoneme(s));
    }
  } else if (suffixVariant && suffixVariant.syllableCount === 0 && suffixSyllables.length > 0) {
    const lastSyl = syllables[syllables.length - 1];
    for (const ss of suffixSyllables) {
      lastSyl.coda.push(...ss.onset, ...ss.nucleus, ...ss.coda);
    }
    suffixSyllables.length = 0;
  }

  if (prefixVariant && prefixVariant.syllableCount === 0 && prefixSyllables.length === 0 && prefixVariant.phonemes.length > 0) {
    const firstSyl = syllables[0];
    for (const s of prefixVariant.phonemes) {
      firstSyl.onset.unshift(resolvePhoneme(s));
    }
  } else if (prefixVariant && prefixVariant.syllableCount === 0 && prefixSyllables.length > 0) {
    const firstSyl = syllables[0];
    for (const ps of prefixSyllables) {
      firstSyl.onset.unshift(...ps.onset, ...ps.nucleus, ...ps.coda);
    }
    prefixSyllables.length = 0;
  }

  if (prefixSyllables.length > 0 && syllables.length > 0) {
    realizeBoundaryHiatus(
      rt, context, prefixSyllables[prefixSyllables.length - 1], syllables[0],
      "prefix-root", prefixSyllables.length, canApplyPrefixRootFallback(rt),
    );
  }

  if (suffixSyllables.length > 0 && syllables.length > 0) {
    realizeBoundaryHiatus(
      rt, context, syllables[syllables.length - 1], suffixSyllables[0],
      "root-suffix", prefixSyllables.length + syllables.length, canApplyRootSuffixFallback(rt),
    );
  }

  const prefixIndices: number[] = [];
  const suffixIndices: number[] = [];

  for (let i = 0; i < prefixSyllables.length; i++) {
    prefixIndices.push(i);
  }
  context.word.syllables = [...prefixSyllables, ...syllables, ...suffixSyllables];
  for (let i = 0; i < suffixSyllables.length; i++) {
    suffixIndices.push(prefixSyllables.length + syllables.length + i);
  }

  if (plan.prefix && prefixIndices.length > 0) {
    adjustStress(context.word.syllables, plan.prefix.stressEffect, prefixIndices, true);
  }
  if (plan.suffix && suffixIndices.length > 0) {
    adjustStress(context.word.syllables, plan.suffix.stressEffect, suffixIndices, false);
  }

  return { plan, prefix, suffix, prefixWritten, suffixWritten, rootSyllableStart: prefixSyllables.length, rules };
}

/** Apply the written halves of the already-resolved morphological rules once. */
export function writeMorphology(context: WordGenerationContext, prepared: PreparedMorphology): MorphologyResult {
  const { plan, prefix, suffix, prefixWritten, suffixWritten } = prepared;
  let rootWritten = context.word.written.clean;
  const fired: FiredMorphophonemicRule[] = [];
  for (const { rule, event } of prepared.rules) {
    const writtenEvent = { ...event };
    if (rule.writtenMatch && rule.writtenReplace !== undefined) {
      const rewritten = rootWritten.replace(rule.writtenMatch, rule.writtenReplace);
      if (rewritten !== rootWritten) {
        writtenEvent.writtenBefore = rootWritten;
        writtenEvent.writtenAfter = rewritten;
        rootWritten = rewritten;
      }
    }
    if (writtenEvent.soundBefore !== undefined || writtenEvent.writtenBefore !== undefined) fired.push(writtenEvent);
  }
  for (const affix of [plan.prefix, plan.suffix]) {
    if (affix?.boundaryTransforms) rootWritten = applyBoundaryTransforms(rootWritten, affix.boundaryTransforms);
  }
  if (context.trace?.morphologyTrace && fired.length > 0) context.trace.morphologyTrace.alternations = fired;
  context.word.written.clean = prefixWritten + rootWritten + suffixWritten;

  const parts: MorphologyWrittenPart[] = [];
  if (prefix) parts.push({ role: "prefix", text: prefixWritten });
  parts.push({ role: "root", text: rootWritten });
  if (suffix) parts.push({ role: "suffix", text: suffixWritten });
  context.word.written.hyphenated = parts.filter(part => part.role === "root" || part.text).map(part => part.text).join("-");
  if (context.trace?.morphologyTrace) {
    context.trace.morphologyTrace.realization = {
      prefix, suffix,
      assembledParts: snapshotWrittenParts(parts),
      emittedParts: snapshotWrittenParts(parts),
    };
  }
  return { prefix, suffix, parts };
}

/** Attach morphology to an already-spelled lexical root; surface realization is separate. */
export function applyMorphology(rt: GeneratorRuntime, context: WordGenerationContext, plan: MorphologyPlan): MorphologyResult {
  const prepared = prepareMorphology(rt, context, plan);
  if (!prepared) return { parts: [{ role: "root", text: context.word.written.clean }] };
  return writeMorphology(context, prepared);
}

export { planMorphology } from "./plan.js";
export type { MorphologyPlan, PlannedMorphologySelection } from "./plan.js";
export { applyMorphology, prepareMorphology, writeMorphology } from "./attach.js";
export type { PreparedMorphology } from "./attach.js";

import { MorphologyConfig, Affix } from "../../config/language.js";
import { GenerationMode, MorphologyTemplate } from "../../types.js";
import getWeightedOption from "../../utils/getWeightedOption.js";
import type { RNG } from "../../utils/random.js";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface MorphologyPlan {
  template: MorphologyTemplate;
  prefix?: Affix;
  suffix?: Affix;
}

export interface PlannedMorphologySelection {
  plan: MorphologyPlan;
  /** Legacy field: baseline affix syllables, never deducted from the root. */
  syllableReduction: number;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function pickWeighted<T>(items: T[], getWeight: (item: T) => number, rand: RNG): T {
  const options: [T, number][] = items.map(item => [item, getWeight(item)]);
  return getWeightedOption(options, rand);
}

function pickTemplate(config: MorphologyConfig, mode: GenerationMode, rand: RNG): MorphologyTemplate {
  const w = config.templateWeights[mode];
  return getWeightedOption<MorphologyTemplate>([
    ["bare", w.bare],
    ["suffixed", w.suffixed],
    ["prefixed", w.prefixed],
    ["both", w.both],
  ], rand);
}

// ---------------------------------------------------------------------------
// Main API
// ---------------------------------------------------------------------------

/**
 * Plan morphology BEFORE root generation — picks template and affixes,
 * returns the plan and baseline affix syllable metadata. Root budgets are independent.
 */
export function planMorphology(
  config: MorphologyConfig,
  mode: GenerationMode,
  rand: RNG,
): PlannedMorphologySelection {
  const template = pickTemplate(config, mode, rand);

  if (template === "bare") {
    return { plan: { template }, syllableReduction: 0 };
  }

  const plan: MorphologyPlan = { template };
  let reduction = 0;

  if (template === "prefixed" || template === "both") {
    plan.prefix = pickWeighted(config.prefixes, a => a.frequency, rand);
    reduction += plan.prefix.syllableCount;
  }
  if (template === "suffixed" || template === "both") {
    plan.suffix = pickWeighted(config.suffixes, a => a.frequency, rand);
    reduction += plan.suffix.syllableCount;
  }

  return { plan, syllableReduction: reduction };
}

import type { AffixSyllable } from "../../config/language.js";
import type { Phoneme } from "../../types.js";

export interface AffixForm {
  written: string;
  phonemes: string[];
  syllables?: AffixSyllable[];
  syllableCount: number;
}

export type AllomorphBoundaryPhoneme = Pick<Phoneme, "sound" | "voiced" | "mannerOfArticulation" | "placeOfArticulation">;

export interface ResolvedAffix {
  planned: AffixForm;
  resolved: AffixForm;
  /** Index in the original configured allomorph array; null selects the base. */
  allomorphIndex: number | null;
  /** Snapshot of the root phone tested before any root alternations. */
  boundaryPhoneme?: AllomorphBoundaryPhoneme;
}

export interface MorphologyWrittenPart {
  role: "prefix" | "root" | "suffix";
  text: string;
}

export interface MorphologyResult {
  prefix?: ResolvedAffix;
  suffix?: ResolvedAffix;
  parts: MorphologyWrittenPart[];
}

export interface MorphologyRealizationTrace {
  prefix?: ResolvedAffix;
  suffix?: ResolvedAffix;
  assembledParts: MorphologyWrittenPart[];
  emittedParts: MorphologyWrittenPart[];
}

export function snapshotAffixForm(form: AffixForm): AffixForm {
  return {
    written: form.written,
    phonemes: [...form.phonemes],
    syllableCount: form.syllableCount,
    syllables: form.syllables?.map(syllable => ({
      onset: [...syllable.onset], nucleus: [...syllable.nucleus], coda: [...syllable.coda],
    })),
  };
}

export function snapshotWrittenParts(parts: MorphologyWrittenPart[]): MorphologyWrittenPart[] {
  return parts.map(part => ({ ...part }));
}

import type { Phoneme, Syllable, WordGenerationContext } from "../types.js";
import type { StressRules } from "../config/language.js";
import getWeightedOption from "../utils/getWeightedOption.js";
import { isNucleusCompatibleWithCoda, isNucleusCompatibleWithFollowingOnset } from "./rime-compatibility.js";
import type { BannedNucleusCodaPairs } from "./rime-compatibility.js";

export interface WordEdges { initial: boolean; final: boolean }

/** Both flags can be true for a single segment with no onset or coda. */
export function nucleusWordEdges(
  syllable: Syllable,
  syllableIndex: number,
  syllableCount: number,
  nucleusIndex: number,
): WordEdges {
  return {
    initial: syllableIndex === 0 && syllable.onset.length === 0 && nucleusIndex === 0,
    final: syllableIndex === syllableCount - 1 && syllable.coda.length === 0 && nucleusIndex === syllable.nucleus.length - 1,
  };
}

/** A zero at either applicable edge wins over the other edge's positive weight. */
export function nucleusWordPositionWeight(phoneme: Phoneme, edges: WordEdges): number | undefined {
  const weights = phoneme.nucleusWordPosition;
  if (!weights) return undefined;
  if ((edges.initial && weights.initial <= 0) || (edges.final && weights.final <= 0)) return 0;
  if (edges.initial) return weights.initial;
  if (edges.final) return weights.final;
  return weights.medial;
}

export function isNucleusWordPositionAllowed(phoneme: Phoneme, edges: WordEdges): boolean {
  const weight = nucleusWordPositionWeight(phoneme, edges);
  return weight === undefined || weight > 0;
}

/** Revalidate realized base-word edges after coda repairs and stress replacement. */
export function repairNucleusWordPositions(
  context: WordGenerationContext,
  nucleusPhonemes: Phoneme[],
  stress: StressRules,
  bannedPairs?: BannedNucleusCodaPairs,
  followingOnsetPairs?: BannedNucleusCodaPairs,
): void {
  const syllables = context.word.syllables;
  for (let si = 0; si < syllables.length; si++) {
    const syllable = syllables[si];
    for (let ni = 0; ni < syllable.nucleus.length; ni++) {
      const original = syllable.nucleus[ni];
      if (!original.nucleusWordPosition) continue;
      const edges = nucleusWordEdges(syllable, si, syllables.length, ni);
      if (isNucleusWordPositionAllowed(original, edges)) continue;

      const initialSyllable = si === 0;
      const finalSyllable = si === syllables.length - 1;
      const nextOnset = ni === syllable.nucleus.length - 1 ? syllables[si + 1]?.onset : undefined;
      const options: [Phoneme, number][] = [];
      let positivePairExclusions = 0;
      let totalWeight = 0;
      for (const candidate of nucleusPhonemes) {
        if (syllable.stress === "ˈ" && stress.nucleus.stressedNucleusBan?.includes(candidate.sound)) continue;
        let positionWeight = nucleusWordPositionWeight(candidate, edges);
        if (positionWeight === undefined) {
          if ((initialSyllable && candidate.startWord <= 0) || (finalSyllable && candidate.endWord <= 0)) continue;
          positionWeight = (initialSyllable && candidate.startWord) || (finalSyllable && candidate.endWord) || candidate.midWord || 1;
        }
        const weight = (candidate.nucleus ?? 0) * positionWeight;
        if (!Number.isFinite(weight) || weight <= 0) continue;
        if (!isNucleusCompatibleWithCoda(candidate.sound, syllable.coda, bannedPairs)
          || !isNucleusCompatibleWithFollowingOnset(candidate.sound, syllable.coda, nextOnset, followingOnsetPairs)) {
          positivePairExclusions++;
          continue;
        }
        options.push([candidate, weight]);
        totalWeight += weight;
      }
      if (options.length === 0 || !Number.isFinite(totalWeight)) {
        throw new Error("No eligible nucleus with finite positive weight for the realized lexical-root position and retained coda.");
      }
      const replacement = getWeightedOption(options, context.rand);
      syllable.nucleus[ni] = replacement;
      context.trace?.recordRepair("repairNucleusWordPositions", original.sound, replacement.sound,
        `base syllable ${si}, nucleus ${ni}; segment initial=${edges.initial}, final=${edges.final}`, {
          domain: "lexical-root", syllableIndex: si, nucleusIndex: ni,
          coda: syllable.coda.map(phoneme => phoneme.sound), edges, weighting: "nucleus-times-word-position",
          eligibleCandidateEntries: options.length, positivePairExclusions, totalWeight,
        });
    }
  }
}

/**
 * Harmonic OT (Noisy Harmonic Grammar) stress assignment.
 *
 * Instead of strict constraint ranking, each constraint has a numeric weight.
 * Candidates are scored by summing (violations × weight) across all constraints.
 * Gaussian noise is optionally added to each constraint weight per evaluation,
 * producing natural stochastic variation within a dialect.
 *
 * @see https://en.wikipedia.org/wiki/Harmonic_Grammar
 * @module
 */

import type { Syllable } from "../types.js";
import type { RNG } from "../utils/random.js";
import { analyzeWordWeight } from "./syllable-weight.js";
import type { SyllableWeightAnalysis } from "./syllable-weight.js";

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

/** A single OT constraint: name + evaluation function. */
export interface OTConstraint {
  /** Human-readable name (e.g. "ALIGN-LEFT"). */
  readonly name: string;
  /**
   * Count violations for placing primary stress on `stressIndex`.
   * Higher = worse.
   */
  evaluate(syllables: Syllable[], stressIndex: number, analysis?: readonly SyllableWeightAnalysis[]): number;
}

/** Per-constraint weight in a Harmonic OT grammar. */
export interface ConstraintWeight {
  /** Must match an {@link OTConstraint.name}. */
  name: string;
  /** Numeric weight (higher = more influential). */
  weight: number;
}

/** Full OT stress configuration stored on LanguageConfig. */
export interface OTStressConfig {
  /** Weighted constraint list. Order doesn't matter (it's harmonic, not ranked). */
  constraints: ConstraintWeight[];
  /**
   * Standard deviation of Gaussian noise added to each weight per evaluation.
   * 0 = deterministic. Typical value: 1–5% of max weight.
   */
  noise?: number;
}

// ---------------------------------------------------------------------------
// Built-in constraints
// ---------------------------------------------------------------------------

/**
 * WEIGHT-TO-STRESS (WSP): penalizes stressing a light syllable when a heavy
 * syllable exists elsewhere in the word.
 *
 * Uses the shared operational classification. The default retains legacy weight.
 */
const WSP: OTConstraint = {
  name: "WSP",
  evaluate(syllables, stressIndex, analysis = analyzeWordWeight(syllables)) {
    if (analysis[stressIndex].operational.weight === "heavy") return 0;
    // One violation per unstressed heavy syllable
    return analysis.filter((s, i) => i !== stressIndex && s.operational.weight === "heavy").length;
  },
};

/**
 * ALIGN-LEFT: penalizes distance of stress from left edge.
 * Violations = number of syllables before the stressed one.
 */
const ALIGN_LEFT: OTConstraint = {
  name: "ALIGN-LEFT",
  evaluate(_syllables, stressIndex) {
    return stressIndex;
  },
};

/**
 * ALIGN-RIGHT: penalizes distance of stress from right edge.
 * Violations = number of syllables after the stressed one.
 */
const ALIGN_RIGHT: OTConstraint = {
  name: "ALIGN-RIGHT",
  evaluate(syllables, stressIndex) {
    return syllables.length - 1 - stressIndex;
  },
};

/**
 * NONFINALITY: penalizes stress on the final syllable.
 * Binary: 1 violation if stress is final, 0 otherwise.
 */
const NONFINALITY: OTConstraint = {
  name: "NONFINALITY",
  evaluate(syllables, stressIndex) {
    return stressIndex === syllables.length - 1 ? 1 : 0;
  },
};

/**
 * NONINITIAL: penalizes stress on the initial syllable, scaled by
 * word length. Shorter words get stronger penalty (1.0 for disyllabic,
 * falling as 2/n for n syllables). This captures the English pattern
 * where short words have more stress variation while longer words
 * lean toward initial stress (Germanic bias).
 */
const NONINITIAL: OTConstraint = {
  name: "NONINITIAL",
  evaluate(syllables, stressIndex) {
    if (stressIndex !== 0) return 0;
    // Steep falloff: full penalty for disyllabic, minimal for 3+
    const n = syllables.length;
    if (n <= 2) return 1;
    return 1 / (n - 1);
  },
};

/** Registry of built-in constraints by name. */
const BUILTIN_CONSTRAINTS: ReadonlyMap<string, OTConstraint> = new Map([
  [WSP.name, WSP],
  [ALIGN_LEFT.name, ALIGN_LEFT],
  [ALIGN_RIGHT.name, ALIGN_RIGHT],
  [NONFINALITY.name, NONFINALITY],
  [NONINITIAL.name, NONINITIAL],
]);

// ---------------------------------------------------------------------------
// Gaussian noise (Box-Muller)
// ---------------------------------------------------------------------------

/**
 * Sample from a Gaussian distribution using Box-Muller transform.
 * Returns a value with mean 0 and the given standard deviation.
 */
function gaussianNoise(stddev: number, rand: RNG): number {
  if (stddev === 0) return 0;
  // Box-Muller requires two uniform samples in (0, 1)
  let u1 = rand();
  const u2 = rand();
  // Guard against log(0)
  if (u1 === 0) u1 = 1e-10;
  return stddev * Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
}

// ---------------------------------------------------------------------------
// Evaluator
// ---------------------------------------------------------------------------

/**
 * Evaluate all candidate stress placements and return the winning index.
 *
 * For each candidate (stress on syllable i), we compute:
 *   harmony(i) = Σ (weight_j + noise_j) × violations_j(i)
 *
 * The candidate with the **lowest** harmony score wins.
 */
export function otEvaluate(
  syllables: Syllable[],
  config: OTStressConfig,
  rand: RNG,
  analysis: readonly SyllableWeightAnalysis[] = analyzeWordWeight(syllables),
): number {
  const n = syllables.length;
  if (n <= 1) return 0;

  const noise = config.noise ?? 0;

  // Resolve constraint objects + perturbed weights once per evaluation
  const resolved: Array<{ constraint: OTConstraint; perturbedWeight: number }> = [];
  for (const cw of config.constraints) {
    const constraint = BUILTIN_CONSTRAINTS.get(cw.name);
    if (!constraint) continue; // skip unknown constraints gracefully
    const perturbedWeight = cw.weight + gaussianNoise(noise, rand);
    resolved.push({ constraint, perturbedWeight });
  }

  let bestIndex = 0;
  let bestScore = Infinity;

  for (let i = 0; i < n; i++) {
    let score = 0;
    for (const { constraint, perturbedWeight } of resolved) {
      score += perturbedWeight * constraint.evaluate(syllables, i, analysis);
    }
    if (score < bestScore) {
      bestScore = score;
      bestIndex = i;
    }
  }

  return bestIndex;
}

// ---------------------------------------------------------------------------
// Exports for testing
// ---------------------------------------------------------------------------

export const _builtinConstraints = BUILTIN_CONSTRAINTS;
export { WSP, ALIGN_LEFT, ALIGN_RIGHT, NONFINALITY, NONINITIAL };

import type { Word } from "../types.js";

export interface PhonemeNormalization {
  generatedAliases?: Record<string, string>;
}

export interface NormalizedPhonemeCounts {
  counts: Record<string, number>;
  /** Raw sounds rejected by normalization, keyed by the original token. */
  losses: Record<string, number>;
}

const PHONEME_TOKEN_RE = /^[\p{Letter}:]+$/u;

/** Coarse corpus aliases are explicit; rejected tokens must be counted by callers. */
export function normalizeGeneratedPhoneme(sound: string, normalization: PhonemeNormalization): string | null {
  if (!sound) return null;
  const unaspirated = sound.replace(/ʰ/g, "");
  const normalized = normalization.generatedAliases?.[unaspirated] ?? unaspirated;
  return PHONEME_TOKEN_RE.test(normalized) ? normalized : null;
}

/** Tallies onset, nucleus and coda phones of each word after normalization. */
export function countNormalizedPhonemes(words: Iterable<Word>, normalization: PhonemeNormalization): NormalizedPhonemeCounts {
  const counts: Record<string, number> = {};
  const losses: Record<string, number> = {};
  for (const word of words) {
    for (const syllable of word.syllables) {
      for (const p of [...syllable.onset, ...syllable.nucleus, ...syllable.coda]) {
        const sound = normalizeGeneratedPhoneme(p.sound, normalization);
        if (sound) counts[sound] = (counts[sound] || 0) + 1;
        else losses[p.sound] = (losses[p.sound] || 0) + 1;
      }
    }
  }
  return { counts, losses };
}

import { compareDistributions, pearson, toPercentMap, totalVariationPct } from "./distribution-quality.js";
import type { DistributionQuality } from "./distribution-quality.js";

export interface PhonemeComparisonRow {
  phoneme: string;
  generatedPct: number;
  baselinePct: number;
  ratio: number;
  gapPct: number;
  absGapPct: number;
}

export interface PhonemeQualityMetrics extends DistributionQuality {
  sharedKeyCount: number;
  generatedOnlyKeyCount: number;
  cmuOnlyKeyCount: number;
  /** Report-only: dominated by common phonemes and blind to scale. */
  sharedPearsonR: number;
  /** Share of phoneme mass (percentage points) misplaced relative to CMU, over all phonemes. */
  totalVariationPct: number;
  nonCmuMassPct: number;
  coverageAdjustedR: number;
  generatedOnlyPhonemes: Array<{ phoneme: string; generatedPct: number }>;
  topOverRepresented: PhonemeComparisonRow[];
  topUnderRepresented: PhonemeComparisonRow[];
  topAbsoluteGap: PhonemeComparisonRow[];
}

export interface PhonemeKeyPartition {
  shared: string[];
  generatedOnly: string[];
  baselineOnly: string[];
}

/** Splits percent maps by presence; explicit zero counts are treated as absent. */
export function partitionPhonemeKeys(
  generatedPct: Record<string, number>,
  baselinePct: Record<string, number>,
): PhonemeKeyPartition {
  const generatedKeys = new Set(Object.keys(generatedPct).filter(key => generatedPct[key] > 0));
  const baselineKeys = new Set(Object.keys(baselinePct).filter(key => baselinePct[key] > 0));
  return {
    shared: [...generatedKeys].filter(k => baselineKeys.has(k)),
    generatedOnly: [...generatedKeys].filter(k => !baselineKeys.has(k)),
    baselineOnly: [...baselineKeys].filter(k => !generatedKeys.has(k)),
  };
}

export function computePhonemeQualityMetrics(
  generatedCounts: Record<string, number>,
  baselineCounts: Record<string, number>,
  minCommonBaselinePct: number,
): PhonemeQualityMetrics {
  const generatedPct = toPercentMap(generatedCounts);
  const baselinePct = toPercentMap(baselineCounts);

  const { shared: sharedKeys, generatedOnly: generatedOnlyKeys, baselineOnly: baselineOnlyKeys } =
    partitionPhonemeKeys(generatedPct, baselinePct);

  const nonCmuMassPct = generatedOnlyKeys.reduce((sum, k) => sum + generatedPct[k], 0);
  const sharedPearsonR = sharedKeys.length > 1
    ? pearson(sharedKeys.map(k => generatedPct[k]), sharedKeys.map(k => baselinePct[k]))
    : 0;
  const coverageAdjustedR = sharedPearsonR * (1 - nonCmuMassPct / 100);

  const commonBaseline = Object.keys(baselinePct).filter(k => baselinePct[k] > 0 && baselinePct[k] >= minCommonBaselinePct);

  const rows = commonBaseline.map((phoneme): PhonemeComparisonRow => {
    const gen = generatedPct[phoneme] || 0;
    const base = baselinePct[phoneme];
    return {
      phoneme,
      generatedPct: gen,
      baselinePct: base,
      ratio: gen / base,
      gapPct: gen - base,
      absGapPct: Math.abs(gen - base),
    };
  });

  const generatedOnlyPhonemes = generatedOnlyKeys
    .map(phoneme => ({ phoneme, generatedPct: generatedPct[phoneme] }))
    .sort((a, b) => b.generatedPct - a.generatedPct);

  return {
    ...compareDistributions(generatedCounts, baselineCounts),
    sharedKeyCount: sharedKeys.length,
    generatedOnlyKeyCount: generatedOnlyKeys.length,
    cmuOnlyKeyCount: baselineOnlyKeys.length,
    sharedPearsonR,
    totalVariationPct: totalVariationPct(generatedPct, baselinePct),
    nonCmuMassPct,
    coverageAdjustedR,
    generatedOnlyPhonemes,
    topOverRepresented: [...rows].sort((a, b) => b.ratio - a.ratio),
    topUnderRepresented: [...rows].sort((a, b) => a.ratio - b.ratio),
    topAbsoluteGap: [...rows].sort((a, b) => b.absGapPct - a.absGapPct),
  };
}

import { Phoneme, Syllable, WordGenerationContext } from "../types.js";
import type { RNG } from "../utils/random.js";
import {
  AspirationPredicate,
  AspirationTargetSelector,
  ResolvedAspirationRules,
  ResolvedStressRules,
  SyllableIndexClass,
  VowelReductionConfig,
} from "../config/language.js";
import { phonemes } from "../elements/phonemes.js";
import getWeightedOption from "../utils/getWeightedOption.js";
import { otEvaluate } from "./ot-stress.js";
import { analyzeWordWeight } from "./syllable-weight.js";
import type { SyllableWeightAnalysis, StressWeightTrace } from "./syllable-weight.js";
import type { AspirationDecisionTrace, AspirationTargetSegment } from "./trace.js";
import { clonePhoneme, cloneSyllables } from "./lexical.js";

/** Fast boolean probability check (avoids tuple array allocation). */
export function coinFlip(rand: RNG, probability: number): boolean {
  return rand() * 100 < probability;
}

export interface PronunciationRuntimeConfig {
  aspiration: ResolvedAspirationRules;
  vowelReduction?: VowelReductionConfig;
}

interface AspirationTargetMatch {
  segment: AspirationTargetSegment;
  index: number;
  phoneme: Phoneme;
}

const applyAspirationMarker = (phoneme: Phoneme): Phoneme => {
  if (phoneme.aspirated) return phoneme;
  const aspirated = clonePhoneme(phoneme);
  aspirated.aspirated = true;
  return aspirated;
};

const getSyllableSegment = (
  syllable: Syllable,
  segment: AspirationTargetSegment,
): Phoneme[] => {
  if (segment === "onset") return syllable.onset;
  if (segment === "nucleus") return syllable.nucleus;
  return syllable.coda;
};

const matchesAspirationTarget = (
  phoneme: Phoneme,
  selector: AspirationTargetSelector,
): boolean => {
  if (selector.sounds && !selector.sounds.includes(phoneme.sound)) return false;
  if (selector.manner && !selector.manner.includes(phoneme.mannerOfArticulation)) return false;
  if (selector.place && !selector.place.includes(phoneme.placeOfArticulation)) return false;
  if (selector.voiced !== undefined && selector.voiced !== phoneme.voiced) return false;
  return true;
};

const findAspirationTarget = (
  syllable: Syllable,
  selectors: AspirationTargetSelector[],
): AspirationTargetMatch | undefined => {
  for (const selector of selectors) {
    const segment = getSyllableSegment(syllable, selector.segment);
    const index = selector.index ?? 0;
    const phoneme = segment[index];
    if (!phoneme) continue;
    if (!matchesAspirationTarget(phoneme, selector)) continue;
    return { segment: selector.segment, index, phoneme };
  }
  return undefined;
};

const classifySyllableIndex = (index: number, syllableCount: number): SyllableIndexClass => {
  if (index === 0) return "initial";
  if (index === syllableCount - 1) return "final";
  return "medial";
};

const matchesAspirationPredicate = (
  predicate: AspirationPredicate,
  syllableIndex: number,
  context: WordGenerationContext,
): boolean => {
  const syllables = context.word.syllables;
  const syllable = syllables[syllableIndex];
  const previous = syllableIndex > 0 ? syllables[syllableIndex - 1] : undefined;

  if (predicate.wordInitial !== undefined && predicate.wordInitial !== (syllableIndex === 0)) {
    return false;
  }
  if (predicate.stressed !== undefined && predicate.stressed !== Boolean(syllable.stress)) {
    return false;
  }
  if (predicate.postStressed !== undefined && predicate.postStressed !== Boolean(previous?.stress)) {
    return false;
  }
  if (
    predicate.syllableIndexClass !== undefined
    && predicate.syllableIndexClass !== classifySyllableIndex(syllableIndex, syllables.length)
  ) {
    return false;
  }
  if (predicate.previousCodaSounds) {
    const previousCoda = previous?.coda.at(-1)?.sound;
    if (!previousCoda || !predicate.previousCodaSounds.includes(previousCoda)) {
      return false;
    }
  }

  return true;
};

const resolveAspirationDecision = (
  syllableIndex: number,
  context: WordGenerationContext,
  rules: ResolvedAspirationRules,
): { ruleId: string | "fallback"; probability: number } => {
  for (const rule of rules.rules) {
    if (matchesAspirationPredicate(rule.when, syllableIndex, context)) {
      return { ruleId: rule.id, probability: rule.probability };
    }
  }
  return { ruleId: "fallback", probability: rules.fallbackProbability };
};

const recordAspirationDecision = (
  context: WordGenerationContext,
  payload: AspirationDecisionTrace,
): void => {
  if (!context.trace) return;
  context.trace.recordStructural(payload);
};

const applyAspiration = (context: WordGenerationContext, rules: ResolvedAspirationRules): void => {
  const syllables = context.word.syllables;

  // Keep hot path lean when tracing is disabled and aspiration is disabled.
  if (!context.trace && !rules.enabled) return;

  for (let i = 0; i < syllables.length; i++) {
    const target = findAspirationTarget(syllables[i], rules.targets);
    const targetSegment = target?.segment ?? null;
    const targetIndex = target?.index ?? null;
    const targetPhoneme = target?.phoneme.sound ?? null;
    const eligible = !!target;

    if (!rules.enabled || !target) {
      recordAspirationDecision(context, {
        event: "aspirationDecision",
        evaluated: false,
        syllableIndex: i,
        ruleId: null,
        probability: null,
        roll: null,
        eligible,
        applied: false,
        targetSegment,
        targetIndex,
        targetPhoneme,
      });
      continue;
    }

    const decision = resolveAspirationDecision(i, context, rules);
    const roll = context.rand() * 100;
    const applied = roll < decision.probability;

    if (applied) {
      const segment = getSyllableSegment(syllables[i], target.segment);
      segment[target.index] = applyAspirationMarker(target.phoneme);
    }

    recordAspirationDecision(context, {
      event: "aspirationDecision",
      evaluated: true,
      syllableIndex: i,
      ruleId: decision.ruleId,
      probability: decision.probability,
      roll: Number(roll.toFixed(5)),
      eligible: true,
      applied,
      targetSegment: target.segment,
      targetIndex: target.index,
      targetPhoneme: target.phoneme.sound,
    });
  }
};

/** @internal exported for testing */
export const _applyAspiration = applyAspiration;

export const applyStress = (context: WordGenerationContext, stress: ResolvedStressRules): void => {
  const { rand } = context;
  const analysis = analyzeWordWeight(context.word.syllables, stress.syllableWeight);
  // Rule 1: Primary stress
  const primaryIndex = applyPrimaryStress(context, rand, stress, analysis);

  // Rule 2: Secondary stress
  const secondary = applySecondaryStress(context, rand, stress, analysis);

  if (context.trace) {
    context.trace.stressWeight = {
      version: 1,
      stage: "applyStress",
      domain: "root-before-nucleus-repair",
      policy: { ...stress.syllableWeight },
      syllables: analysis,
      primary: { strategy: stress.primary.type, selectedIndex: primaryIndex },
      secondary,
    };
  }

  // Rule 3: Rhythmic stress
  applyRhythmicStress(context, rand, stress);
};

const chooseWeightSensitivePrimaryStress = (
  syllables: Syllable[],
  rand: RNG,
  disyllabicWeights: [number, number],
  polysyllabicWeights: {
    heavyPenult: number;
    lightPenult: number;
    antepenultHeavy: number;
    antepenultLight: number;
    initial: number;
  },
  analysis: readonly SyllableWeightAnalysis[],
): number => {
  if (syllables.length === 2) {
    return getWeightedOption([[0, disyllabicWeights[0]], [1, disyllabicWeights[1]]], rand);
  }

  const penultimateIndex = syllables.length - 2;
  const antepenultIndex = Math.max(0, syllables.length - 3);
  const penultimateHeavy = analysis[penultimateIndex].operational.weight === "heavy";

  const penultWeight = penultimateHeavy
    ? polysyllabicWeights.heavyPenult
    : polysyllabicWeights.lightPenult;
  const antepenultWeight = penultimateHeavy
    ? polysyllabicWeights.antepenultHeavy
    : polysyllabicWeights.antepenultLight;

  return getWeightedOption([
    [penultimateIndex, penultWeight],
    [antepenultIndex, antepenultWeight],
    [0, polysyllabicWeights.initial],
  ], rand);
};

const applyPrimaryStress = (context: WordGenerationContext, rand: RNG, stress: ResolvedStressRules, analysis: readonly SyllableWeightAnalysis[]): number | null => {
  const syllables = context.word.syllables;
  const syllableCount = syllables.length;

  if (syllableCount <= 1) {
    // Lexical prominence survives affixation; IPA can omit the display mark.
    if (syllableCount === 1) syllables[0].stress = "ˈ";
    return null;
  }

  let primaryStressIndex = 0;

  switch (stress.primary.type) {
  case "fixed": {
    primaryStressIndex = Math.max(0, Math.min(syllableCount - 1, stress.primary.fixedPosition));
    break;
  }
  case "initial": {
    primaryStressIndex = 0;
    break;
  }
  case "penultimate": {
    primaryStressIndex = Math.max(0, syllableCount - 2);
    break;
  }
  case "weight-sensitive": {
    primaryStressIndex = chooseWeightSensitivePrimaryStress(
      syllables,
      rand,
      stress.primary.disyllabicWeights,
      stress.primary.polysyllabicWeights,
      analysis,
    );
    break;
  }
  case "ot": {
    primaryStressIndex = otEvaluate(syllables, stress.primary.otConfig, rand, analysis);
    break;
  }
  }

  syllables[primaryStressIndex].stress = "ˈ";
  return primaryStressIndex;
};

const applySecondaryStress = (context: WordGenerationContext, rand: RNG, stress: ResolvedStressRules, analysis: readonly SyllableWeightAnalysis[]): StressWeightTrace["secondary"] => {
  const syllables = context.word.syllables;
  const syllableCount = syllables.length;
  const skipped: StressWeightTrace["secondary"] = { candidates: [], selectedIndex: null, applied: false };

  if (syllableCount <= 1 || !stress.secondary.enabled) return skipped;

  const primaryStressIndex = syllables.findIndex((s) => s.stress === "ˈ");
  if (primaryStressIndex < 0) return skipped;

  const potentialIndices = (
    stress.secondary.candidateWindow === "all-nonprimary"
      ? Array.from({ length: syllableCount }, (_, i) => i)
      : [0, 1, 2].filter((i) => i < syllableCount)
  ).filter((i) => i !== primaryStressIndex);

  if (potentialIndices.length === 0) return skipped;

  const candidates = potentialIndices.map((i) => ({
    syllableIndex: i,
    weight: analysis[i].operational.weight === "heavy" ? stress.secondary.heavyWeight : stress.secondary.lightWeight,
  }));

  const secondaryStressIndex = getWeightedOption(
    candidates.map(candidate => [candidate.syllableIndex, candidate.weight]),
    rand,
  );

  const applied = coinFlip(rand, stress.secondary.probability);
  if (applied) {
    syllables[secondaryStressIndex].stress = "ˌ";
  }
  return { candidates, selectedIndex: secondaryStressIndex, applied };
};

const applyRhythmicStress = (context: WordGenerationContext, rand: RNG, stress: ResolvedStressRules): void => {
  const syllables = context.word.syllables;
  if (!stress.rhythmic.enabled) return;

  for (let i = 1; i < syllables.length - 1; i++) {
    if (syllables[i].stress) continue;

    const hasUnstressedNeighbors = !syllables[i - 1].stress && !syllables[i + 1].stress;
    if (stress.rhythmic.requireUnstressedNeighbors && !hasUnstressedNeighbors) {
      continue;
    }

    if (coinFlip(rand, stress.rhythmic.probability)) {
      syllables[i].stress = "ˌ";
    }
  }
};

const buildPronunciationGuide = (context: WordGenerationContext): void => {
  const { syllables } = context.word;
  let guide = "";
  const render = (phoneme: Phoneme): string =>
    phoneme.aspirated && !phoneme.sound.endsWith("ʰ")
      ? `${phoneme.sound}ʰ`
      : phoneme.sound;

  for (let index = 0; index < syllables.length; index++) {
    const syllable = syllables[index];

    // Add stress/separator prefix
    if (syllable.stress === "ˈ" && syllables.length > 1) guide += "ˈ";
    else if (syllable.stress === "ˌ") guide += "ˌ";
    else if (index > 0) guide += ".";

    for (let i = 0; i < syllable.onset.length; i++) guide += render(syllable.onset[i]);
    for (let i = 0; i < syllable.nucleus.length; i++) guide += render(syllable.nucleus[i]);
    for (let i = 0; i < syllable.coda.length; i++) guide += render(syllable.coda[i]);
  }

  context.word.pronunciation = guide;
};

/**
 * Post-generation pass: reduce vowels in unstressed syllables.
 *
 * Only vowels with a matching rule in the config are candidates.
 * Tense vowels are skipped. Per-rule target and probability are used,
 * modified by syllable position and secondary stress settings.
 *
 * NOTE: Spelling intentionally does NOT update after vowel reduction.
 * English uses etymological/historical spelling — the written form is
 * generated before pronunciation, so reduction only affects the IPA
 * output (e.g. we produce "banana" not "bənænə"). This mirrors real
 * English orthography where unstressed vowels are spelled with their
 * full letters despite being pronounced as schwa.
 */
const reduceUnstressedVowels = (
  context: WordGenerationContext,
  config: VowelReductionConfig,
  rand: RNG,
): void => {
  const { word } = context;
  const syllables = word.syllables;

  // Monosyllabic words don't reduce
  if (syllables.length <= 1) return;

  // Build a lookup map for rules by source sound
  const ruleMap = new Map(config.rules.map((r) => [r.source, r]));

  for (let si = 0; si < syllables.length; si++) {
    const syllable = syllables[si];

    // Primary-stressed syllables never reduce
    if (syllable.stress === "ˈ") continue;

    // Secondary-stressed syllables: only reduce if config allows
    if (syllable.stress === "ˌ") {
      if (!config.reduceSecondaryStress) continue;
    }

    // Determine positional modifier
    let positionalMod = 1.0;
    if (config.positionalModifiers) {
      if (si === 0) {
        positionalMod = config.positionalModifiers.wordInitial ?? 1.0;
      } else if (si === syllables.length - 1) {
        positionalMod = config.positionalModifiers.wordFinal ?? 1.0;
      } else {
        positionalMod = config.positionalModifiers.wordMedial ?? 1.0;
      }
    }

    for (let i = 0; i < syllable.nucleus.length; i++) {
      const vowel = syllable.nucleus[i];

      // Skip tense vowels — they resist reduction
      if (vowel.tense) continue;

      // Look up rule; if not found, vowel is immune
      const rule = ruleMap.get(vowel.sound);
      if (!rule) continue;

      // Compute effective probability
      let prob = rule.probability * positionalMod;
      if (syllable.stress === "ˌ" && config.secondaryStressProbability != null) {
        prob = prob * (config.secondaryStressProbability / 100);
      }
      prob = Math.min(100, Math.max(0, Math.round(prob)));

      // Find target phoneme from inventory
      const target = phonemes.find((p) => p.sound === rule.target);
      if (!target) continue;

      if (coinFlip(rand, prob)) {
        const reduced = clonePhoneme(target);
        reduced.reduced = true;
        syllable.nucleus[i] = reduced;
      }
    }
  }
};

/** @internal exported for testing */
export const _reduceUnstressedVowels = reduceUnstressedVowels;

export const generatePronunciation = (
  context: WordGenerationContext,
  pronunciation: PronunciationRuntimeConfig,
): void => {
  if (context.word.lexical) {
    context.word.syllables = cloneSyllables(context.word.lexical.syllables);
  }
  applyAspiration(context, pronunciation.aspiration);
  if (pronunciation.vowelReduction?.enabled) {
    reduceUnstressedVowels(context, pronunciation.vowelReduction, context.rand);
  }
  buildPronunciationGuide(context);
};

import type { AttemptAssessment, AttemptScore } from "./length-semantics.js";
import type { AttemptLengths, PrunedAttemptLengths, SelectionTrace } from "./trace.js";

/** Observes existing decisions without choosing candidates or consuming randomness. */
export class RejectionTraceCollector {
  private readonly proposals = new Map<string, AttemptLengths & { count: number }>();
  private readonly pruned = new Map<string, PrunedAttemptLengths & { count: number }>();
  /** Indexed by attempt; pruned attempts hold no score and are never selected. */
  private readonly attempts: Array<(AttemptLengths & { score: AttemptScore }) | undefined> = [];
  private readonly reasons: SelectionTrace["rejectionReasons"] = {
    phonemeTarget: 0, letterLength: 0, warmup: 0,
  };
  private rejectedAttempts = 0;

  constructor(
    private readonly criteria: SelectionTrace["criteria"],
  ) {}

  record(lengths: AttemptLengths, score: AttemptScore, assessment: AttemptAssessment): void {
    this.attempts.push({ ...lengths, score: { ...score } });
    const key = `${lengths.syllables}/${lengths.phonemes}/${lengths.letters}`;
    const bin = this.proposals.get(key) ?? { ...lengths, count: 0 };
    bin.count++;
    this.proposals.set(key, bin);
    if (assessment.acceptedBy) return;

    this.rejectedAttempts++;
    if (assessment.failed.phonemeTarget) this.reasons.phonemeTarget++;
    if (assessment.failed.letterLength) this.reasons.letterLength++;
    if (assessment.failed.warmup) this.reasons.warmup++;
  }

  /** Record an attempt rejected on its phoneme count before spelling. */
  recordPruned(lengths: PrunedAttemptLengths): void {
    this.attempts.push(undefined);
    const key = `${lengths.syllables}/${lengths.phonemes}`;
    const bin = this.pruned.get(key) ?? { ...lengths, count: 0 };
    bin.count++;
    this.pruned.set(key, bin);
    this.rejectedAttempts++;
    this.reasons.phonemeTarget++;
  }

  finish(selectedAttempt: number, acceptedBy: SelectionTrace["acceptedBy"]): SelectionTrace {
    const selected = this.attempts[selectedAttempt];
    if (!selected) throw new Error(`Selected attempt ${selectedAttempt} was not scored`);
    return {
      status: acceptedBy === null ? "fallback" : "accepted",
      acceptedBy,
      attemptsExecuted: this.attempts.length,
      selectedAttempt,
      rejectedAttempts: this.rejectedAttempts,
      rejectionReasons: { ...this.reasons },
      criteria: { ...this.criteria },
      selected,
      proposedLengths: [...this.proposals.values()],
      prunedLengths: [...this.pruned.values()],
    };
  }
}

/**
 * Phonotactic repair pass — runs on generated syllables AFTER syllable
 * generation, BEFORE write and pronounce. Fixes cross-syllable cluster
 * violations and word-final phoneme violations.
 */
import { Phoneme, Syllable } from "../types.js";
import type { ClusterLimits, SonorityConstraints, CodaConstraints } from "../config/language.js";
import type { TraceCollector } from "./trace.js";

/**
 * Repair cross-syllable consonant cluster violations.
 * Scans each syllable boundary and applies the configured repair strategy.
 */
export function repairClusters(
  syllables: Syllable[],
  bannedSet: Set<string>,
  repair: "drop-coda" | "drop-onset",
  trace?: TraceCollector,
): void {

  for (let i = 0; i < syllables.length - 1; i++) {
    const coda = syllables[i].coda;
    const onset = syllables[i + 1].onset;

    if (coda.length === 0 || onset.length === 0) continue;

    const codaBefore = trace ? coda.map(p => p.sound).join(",") : "";
    const onsetBefore = trace ? onset.map(p => p.sound).join(",") : "";

    // Drop phonemes until the boundary is legal (or one side is empty)
    while (coda.length > 0 && onset.length > 0 &&
           bannedSet.has(`${coda[coda.length - 1].sound}|${onset[0].sound}`)) {
      if (repair === "drop-coda") coda.pop();
      else onset.shift();
    }

    if (trace) {
      const codaAfter = coda.map(p => p.sound).join(",");
      const onsetAfter = onset.map(p => p.sound).join(",");
      trace.recordRepair("repairClusters", `${codaBefore}|${onsetBefore}`, `${codaAfter}|${onsetAfter}`, `boundary ${i}→${i+1}, strategy: ${repair}`);
    }
  }
}

/**
 * Repair word-final coda violations.
 * If the last phoneme in the last syllable's coda is not in the allowed list, drop it.
 */
export function repairFinalCoda(
  syllables: Syllable[],
  allowedFinalSet: Set<string>,
  trace?: TraceCollector,
): void {
  if (syllables.length === 0) return;

  const lastSyllable = syllables[syllables.length - 1];
  const coda = lastSyllable.coda;

  if (coda.length === 0) return;

  const before = trace ? coda.map(p => p.sound).join(",") : "";

  // Keep dropping disallowed final phonemes
  while (coda.length > 0 && !allowedFinalSet.has(coda[coda.length - 1].sound)) {
    coda.pop();
  }

  if (trace) {
    trace.recordRepair("repairFinalCoda", before, coda.map(p => p.sound).join(","), "dropped disallowed final phonemes");
  }
}

import { isObstruent, isNasal, isStop } from "../utils/phonemes.js";

// ---------------------------------------------------------------------------
// Place-of-articulation grouping for homorganic nasal+stop
// ---------------------------------------------------------------------------

const PLACE_GROUP_MAP = new Map<string, string>([
  ["m", "bilabial"], ["p", "bilabial"], ["b", "bilabial"],
  ["n", "alveolar"], ["t", "alveolar"], ["d", "alveolar"],
  ["ŋ", "velar"],    ["k", "velar"],    ["g", "velar"],
]);

function getPlaceGroup(sound: string): string | undefined {
  return PLACE_GROUP_MAP.get(sound);
}

// ---------------------------------------------------------------------------
// Cluster shape repair (safety net)
// ---------------------------------------------------------------------------

export interface ClusterShapeOptions {
  clusterLimits?: ClusterLimits;
  sonorityConstraints?: SonorityConstraints;
  codaConstraints?: CodaConstraints;
  sonorityBySound?: Map<string, number>;
  codaAppendantSet?: Set<string>;
  sonorityExemptSet?: Set<string>;
}

/**
 * Repair cluster shapes: truncate over-long clusters, enforce voicing
 * agreement among coda obstruents, enforce homorganic nasal+stop.
 */
export function repairClusterShape(
  syllables: Syllable[],
  opts: ClusterShapeOptions,
  trace?: TraceCollector,
): void {
  for (let si = 0; si < syllables.length; si++) {
    const syl = syllables[si];

    // --- Truncate over-long onsets ---
    if (opts.clusterLimits && syl.onset.length > opts.clusterLimits.maxOnset) {
      const before = trace ? syl.onset.map(p => p.sound).join(",") : "";
      syl.onset.splice(0, syl.onset.length - opts.clusterLimits.maxOnset);
      if (trace) trace.recordRepair("repairClusterShape:onsetTruncate", before, syl.onset.map(p => p.sound).join(","), `syl ${si}`);
    }

    // --- Truncate over-long codas ---
    if (opts.clusterLimits && syl.coda.length > 0) {
      const cl = opts.clusterLimits;
      const lastSound = syl.coda[syl.coda.length - 1].sound;
      const effectiveMax = opts.codaAppendantSet?.has(lastSound)
        ? cl.maxCoda + 1
        : cl.maxCoda;
      if (syl.coda.length > effectiveMax) {
        const before = trace ? syl.coda.map(p => p.sound).join(",") : "";
        while (syl.coda.length > effectiveMax) {
          syl.coda.shift();
        }
        if (trace) trace.recordRepair("repairClusterShape:codaTruncate", before, syl.coda.map(p => p.sound).join(","), `syl ${si}`);
      }
    }

    // --- Voicing agreement among coda obstruents ---
    if (opts.codaConstraints?.voicingAgreement && syl.coda.length >= 2) {
      const before = trace ? syl.coda.map(p => p.sound).join(",") : "";
      repairVoicingAgreement(syl.coda);
      if (trace) trace.recordRepair("repairClusterShape:voicingAgreement", before, syl.coda.map(p => p.sound).join(","), `syl ${si}`);
    }

    // --- Homorganic nasal+stop ---
    if (opts.codaConstraints?.homorganicNasalStop && syl.coda.length >= 2) {
      const before = trace ? syl.coda.map(p => p.sound).join(",") : "";
      repairHomorganicNasalStop(syl.coda);
      if (trace) trace.recordRepair("repairClusterShape:homorganicNasalStop", before, syl.coda.map(p => p.sound).join(","), `syl ${si}`);
    }
  }
}

/**
 * Enforce voicing agreement: all obstruents in a coda cluster must share
 * the same voicing. The last obstruent wins; drop earlier ones that disagree.
 */
function repairVoicingAgreement(coda: Phoneme[]): void {
  // Find the last obstruent to determine target voicing
  let lastObsIdx = -1;
  for (let i = coda.length - 1; i >= 0; i--) {
    if (isObstruent(coda[i])) { lastObsIdx = i; break; }
  }
  if (lastObsIdx < 0) return;

  const targetVoiced = coda[lastObsIdx].voiced;
  for (let i = coda.length - 2; i >= 0; i--) {
    if (isObstruent(coda[i]) && coda[i].voiced !== targetVoiced) {
      coda.splice(i, 1);
    }
  }
}

/**
 * Enforce homorganic nasal+stop: if a nasal is immediately followed by a stop
 * in the coda and they disagree in place, drop the nasal.
 */
function repairHomorganicNasalStop(coda: Phoneme[]): void {
  for (let i = coda.length - 2; i >= 0; i--) {
    if (isNasal(coda[i]) && isStop(coda[i + 1])) {
      const nasalPlace = getPlaceGroup(coda[i].sound);
      const stopPlace = getPlaceGroup(coda[i + 1].sound);
      if (nasalPlace && stopPlace && nasalPlace !== stopPlace) {
        coda.splice(i, 1);
      }
    }
  }
}

/**
 * Strip sibilants (/s/, /z/) that follow /ŋ/ in a coda — these clusters
 * only arise across morpheme boundaries in English (e.g. "songs" = song+s).
 *
 * Other post-/ŋ/ consonants are left alone:
 * - /k/, /g/ — homorganic stops (think, bank)
 * - /θ/ — monomorphemic (length, strength)
 * - /t/, /d/ — morphologically valid (thanked, longed)
 */
// ---------------------------------------------------------------------------
// /h/ after back vowels — phonotactic constraint
// ---------------------------------------------------------------------------

const BACK_VOWEL_NUCLEI = new Set(["ʌ", "ʊ"]);

/**
 * Penalize /h/ onset after /ʌ/ or /ʊ/ nucleus with empty coda.
 * In English this pattern only occurs at morpheme boundaries (un-happy).
 * We drop the /h/ onset, leaving the next syllable onsetless.
 */
export function repairHAfterBackVowel(syllables: Syllable[], trace?: TraceCollector): void {
  for (let i = 0; i < syllables.length - 1; i++) {
    const curr = syllables[i];
    const next = syllables[i + 1];

    if (
      curr.coda.length === 0 &&
      curr.nucleus.length > 0 &&
      BACK_VOWEL_NUCLEI.has(curr.nucleus[curr.nucleus.length - 1].sound) &&
      next.onset.length === 1 &&
      next.onset[0].sound === "h"
    ) {
      next.onset.splice(0, 1);
      trace?.recordRepair("repairHAfterBackVowel", "h", "", `dropped /h/ onset after /${curr.nucleus[curr.nucleus.length - 1].sound}/ at syl ${i}→${i+1}`);
    }
  }
}

// ---------------------------------------------------------------------------
// /h/ after back vowels — phonotactic constraint
// ---------------------------------------------------------------------------

import type { CodaConstraints } from "../config/language.js";
import type { Phoneme, Syllable } from "../types.js";

export type BannedNucleusCodaPairs = ReadonlyMap<string, ReadonlySet<string>>;

type NucleusCodaRule = NonNullable<CodaConstraints["bannedNucleusCodaCombinations"]>[number];

/**
 * Index configured nucleus/coda rules by nucleus sound. With
 * `followingOnsetOnly`, keep only the rules that also ban the consonant as the
 * next root syllable's first onset phoneme after an open syllable.
 */
export function buildBannedNucleusPairs(
  rules: readonly NucleusCodaRule[] | undefined,
  followingOnsetOnly = false,
): Map<string, Set<string>> | undefined {
  if (!rules) return undefined;
  const map = new Map<string, Set<string>>();
  for (const { nucleus, coda, followingOnset } of rules) {
    if (followingOnsetOnly && !followingOnset) continue;
    for (const n of nucleus) {
      const banned = map.get(n) ?? new Set<string>();
      for (const c of coda) banned.add(c);
      map.set(n, banned);
    }
  }
  return followingOnsetOnly && map.size === 0 ? undefined : map;
}

/** Configured exclusions apply to any nucleus/coda pair within a syllable. */
export function isNucleusCodaPairAllowed(
  nucleus: string,
  coda: string,
  bannedPairs?: BannedNucleusCodaPairs,
): boolean {
  return !bannedPairs?.get(nucleus)?.has(coda);
}

export function isNucleusCompatibleWithCoda(
  nucleus: string,
  coda: readonly Phoneme[],
  bannedPairs?: BannedNucleusCodaPairs,
): boolean {
  return coda.every(phoneme => isNucleusCodaPairAllowed(nucleus, phoneme.sound, bannedPairs));
}

/**
 * An open syllable's nucleus is directly followed by the next root syllable's
 * first onset phoneme; a closed syllable's coda sits between them.
 */
export function isNucleusCompatibleWithFollowingOnset(
  nucleus: string,
  coda: readonly Phoneme[],
  nextOnset: readonly Phoneme[] | undefined,
  followingOnsetPairs?: BannedNucleusCodaPairs,
): boolean {
  if (coda.length > 0 || !nextOnset?.length) return true;
  return isNucleusCodaPairAllowed(nucleus, nextOnset[0].sound, followingOnsetPairs);
}

/** Check the lexical root before spelling, surface reduction, and affix assembly. */
export function assertRootRimeCompatibility(
  syllables: readonly Syllable[],
  bannedPairs?: BannedNucleusCodaPairs,
  followingOnsetPairs?: BannedNucleusCodaPairs,
): void {
  if (!bannedPairs?.size && !followingOnsetPairs?.size) return;
  for (const [si, syllable] of syllables.entries()) {
    for (const [ni, nucleus] of syllable.nucleus.entries()) {
      for (const [ci, coda] of syllable.coda.entries()) {
        if (!isNucleusCodaPairAllowed(nucleus.sound, coda.sound, bannedPairs)) {
          throw new Error(`Excluded lexical-root nucleus/coda pair /${nucleus.sound}/ + /${coda.sound}/ at syllable ${si}, nucleus ${ni}, coda ${ci}.`);
        }
      }
    }
    const lastNucleus = syllable.nucleus.at(-1);
    const nextOnset = syllables[si + 1]?.onset;
    if (lastNucleus && !isNucleusCompatibleWithFollowingOnset(lastNucleus.sound, syllable.coda, nextOnset, followingOnsetPairs)) {
      throw new Error(`Excluded lexical-root nucleus/onset pair /${lastNucleus.sound}/ + /${nextOnset![0].sound}/ at syllables ${si}-${si + 1}.`);
    }
  }
}

import type { WrittenFormConstraints } from "../config/language.js";
import type { SpellingBudgetKey, SpellingBudgetMeasurement, SpellingBudgetValues } from "./spelling-coverage-types.js";
import { isVowelChar } from "../utils/letters.js";

/** Default English consonant graphemes (longest first for greedy matching). */
export const DEFAULT_CONSONANT_GRAPHEMES = ["tch", "dge", "ch", "sh", "th", "ng", "ph", "wh", "ck"];

/**
 * Tokenize a string into grapheme units using longest-match-first.
 * Multi-letter consonant graphemes (e.g. "tch", "ch", "sh") are treated as
 * atomic units. Remaining characters become single-letter tokens.
 *
 * @example tokenizeGraphemes("tchwng") → ["tch", "w", "ng"]
 * @example tokenizeGraphemes("strengths") → ["s", "t", "r", "e", "ng", "th", "s"]
 */
export function tokenizeGraphemes(str: string, graphemeList: string[] = DEFAULT_CONSONANT_GRAPHEMES): string[] {
  const tokens: string[] = [];
  let i = 0;
  while (i < str.length) {
    let matched = false;
    // Try longest graphemes first (list is pre-sorted longest first)
    for (const g of graphemeList) {
      if (str.startsWith(g, i)) {
        tokens.push(g);
        i += g.length;
        matched = true;
        break;
      }
    }
    if (!matched) {
      tokens.push(str[i]);
      i++;
    }
  }
  return tokens;
}

/** Check if a grapheme token is a consonant (contains no vowel letters). */
export function isConsonantToken(token: string, tokenIdx?: number, allTokens?: string[]): boolean {
  const fullStr = allTokens ? allTokens.join("") : token;
  // Compute char offset of this token within the full string
  let charOffset = 0;
  if (allTokens && tokenIdx !== undefined) {
    for (let t = 0; t < tokenIdx; t++) charOffset += allTokens[t].length;
  }
  for (let i = 0; i < token.length; i++) {
    if (isVowelChar(token[i], charOffset + i, fullStr)) return false;
  }
  return true;
}

/** Measure every configured preference on the complete proposed surface. */
export function measureSpellingBudgets(surface: string, constraints: WrittenFormConstraints | undefined): SpellingBudgetMeasurement {
  const values: SpellingBudgetValues = { consonantGraphemes: 0, consonantLetters: 0, finalConsonantLetters: 0, vowelLetters: 0 };
  let consonants = 0;
  let vowels = 0;
  for (let i = 0; i < surface.length; i++) {
    const vowel = isVowelChar(surface[i], i, surface);
    consonants = vowel ? 0 : consonants + 1;
    vowels = vowel ? vowels + 1 : 0;
    values.consonantLetters = Math.max(values.consonantLetters, consonants);
    values.vowelLetters = Math.max(values.vowelLetters, vowels);
  }
  values.finalConsonantLetters = consonants;
  const tokens = tokenizeGraphemes(surface, constraints?.consonantGraphemes);
  let tokenRun = 0;
  let charOffset = 0;
  for (const token of tokens) {
    let consonantToken = true;
    for (let i = 0; i < token.length; i++) {
      // Preserve right context across token boundaries, including contextual y.
      if (isVowelChar(token[i], charOffset + i, surface)) {
        consonantToken = false;
        break;
      }
    }
    tokenRun = consonantToken ? tokenRun + 1 : 0;
    values.consonantGraphemes = Math.max(values.consonantGraphemes, tokenRun);
    charOffset += token.length;
  }
  const limits: Partial<SpellingBudgetValues> = {};
  const configured: Array<[SpellingBudgetKey, number | undefined]> = [
    ["consonantGraphemes", constraints?.maxConsonantGraphemes],
    ["consonantLetters", constraints?.maxConsonantLetters],
    ["finalConsonantLetters", constraints?.maxFinalConsonantLetters],
    ["vowelLetters", constraints?.maxVowelLetters],
  ];
  for (const [key, value] of configured) if (value) limits[key] = value;
  return { values, limits, exceeded: configured.filter(([key, limit]) => !!limit && values[key] > limit).map(([key]) => key) };
}

import type { SpellingPhone } from "./base-spelling.js";
import type { GraphemeSlot } from "./grapheme-selection.js";
import type { DoublingSlot } from "./spelling-doubling.js";

export interface SpellingBoundaryContext {
  slot: GraphemeSlot;
  doubling: Omit<DoublingSlot, "form" | "nucleusForm">;
}

/** Derive all fixed eligibility inputs from the detached, actual writer boundary. */
export function spellingBoundaryContexts(phones: readonly SpellingPhone[]): SpellingBoundaryContext[] {
  const syllableCount = phones.reduce((count, phone) => Math.max(count, phone.syllableIndex + 1), 0);
  const shapes = Array.from({ length: syllableCount }, () => ({ onset: 0, nucleus: 0, coda: 0 }));
  for (const [index, phone] of phones.entries()) {
    if (!phone.boundary || phone.id !== index || phone.soundAtSpelling !== phone.boundary.phoneme.sound ||
        !shapes[phone.syllableIndex] || phone.segmentIndex !== shapes[phone.syllableIndex][phone.segment]) {
      throw new Error("Invalid spelling evidence: writer boundary");
    }
    shapes[phone.syllableIndex][phone.segment]++;
  }
  return phones.map((entry, index) => {
    const previous = phones[index - 1];
    const next = phones[index + 1];
    const phoneme = entry.boundary!.phoneme;
    const prevPhoneme = previous?.boundary!.phoneme;
    const stress = entry.boundary!.stress;
    const position = entry.segment;
    const syllableIndex = entry.syllableIndex;
    const isCluster = (previous?.syllableIndex === syllableIndex && previous.segment === position) ||
      (next?.syllableIndex === syllableIndex && next.segment === position);
    const shape = shapes[syllableIndex];
    return {
      slot: { phoneme, prevPhoneme, nextPhoneme: next?.boundary!.phoneme,
        index, total: phones.length, position, syllableIndex, syllableCount,
        onsetLength: shape.onset, nucleusLength: shape.nucleus, codaLength: shape.coda, isCluster, stress,
        ...(previous ? { previousPosition: previous.segment } : {}),
        ...(entry.boundary!.nextWritten ? { nextWritten: entry.boundary!.nextWritten } : {}) },
      doubling: { phoneme, position, prevPhoneme,
        nextNucleus: phones.slice(index + 1).find(phone => phone.segment === "nucleus")?.boundary!.phoneme,
        stress, prevReduced: prevPhoneme?.reduced ?? false, isCluster,
        isFirstInCoda: position === "coda" && previous?.segment !== "coda",
        isLastPhoneme: index === phones.length - 1, isEndOfWord: syllableIndex === syllableCount - 1,
        isMonosyllabic: syllableCount === 1,
        nextIsConsonant: next?.segment === "onset" || (next?.syllableIndex === syllableIndex && next.segment === "coda") },
    };
  });
}

