function unitSpans(cells: readonly SpellingCell[], choices: SpellingChoiceState[]): Map<number, UnitSpan> {
  const spans = new Map<number, UnitSpan>();
  for (const [unitId, choice] of choices.entries()) {
    const indices: number[] = [];
    cells.forEach((cell, i) => { if (owner(cell) === unitId) indices.push(i); });
    const start = indices[0];
    const selected = indices.map(i => cells[i]);
    if (selected.length !== choice.form.length || selected.length === 0 ||
        selected.some((cell, i) => indices[i] !== start + i || cell.origin.kind === "rewrite" ||
          cell.origin.offset !== i || cell.partId !== choice.slot.syllableIndex) ||
        selected.map(cell => cell.text).join("") !== choice.form) continue;
    spans.set(unitId, { start, end: start + selected.length, partId: choice.slot.syllableIndex, cells: selected });
  }
  return spans;
}

function project(cells: readonly SpellingCell[], spans: Map<number, UnitSpan>, changes: Map<number, string>): SurfaceCell[] {
  const starts = new Map([...spans].map(([id, span]) => [span.start, { id, span }]));
  const result: SurfaceCell[] = [];
  for (let i = 0; i < cells.length;) {
    const entry = starts.get(i);
    const form = entry && changes.get(entry.id);
    if (entry && form !== undefined) {
      for (const text of form) result.push({ text, unitId: entry.id, partId: entry.span.partId });
      i = entry.span.end;
    } else {
      const cell = cells[i++];
      result.push({ text: cell.text, unitId: owner(cell), partId: cell.partId ?? null });
    }
  }
  return result;
}

function readingContext(cells: SurfaceCell[], unitId: number): { previous: string; next: string; open: boolean; neighbors: Array<number | null> } | undefined {
  const own = cells.flatMap((cell, i) => cell.unitId === unitId ? [i] : []);
  if (!own.length) return undefined;
  const end = own[own.length - 1];
  const partId = cells[end].partId;
  return {
    previous: cells[own[0] - 1]?.text.toLowerCase() ?? "",
    next: cells[end + 1]?.text.toLowerCase() ?? "",
    neighbors: [cells[own[0] - 1]?.unitId ?? null, cells[end + 1]?.unitId ?? null],
    open: partId !== null && !cells.slice(end + 1).some(cell => cell.partId === partId || cell.partId === null),
  };
}

function checkReadings(original: SurfaceCell[], proposed: SurfaceCell[], choices: SpellingChoiceState[], options: Option[], changed: Set<number>): SpellingBudgetRefusal | undefined {
  const changedParts = new Set([...changed].map(id => choices[id].slot.syllableIndex));
  if (proposed.some(cell => cell.unitId === null && (cell.partId === null || changedParts.has(cell.partId)))) return "unresolved-ownership";
  for (let unitId = 0; unitId < choices.length; unitId++) {
    const reading = options[unitId].reading;
    const samePart = changedParts.has(choices[unitId].slot.syllableIndex);
    if (samePart && !reading) return "unknown-reading";
    if (samePart && reading?.kind === "unsupported-construction") return "construction-obligation";
    const before = readingContext(original, unitId);
    const after = readingContext(proposed, unitId);
    const changedNeighbor = [...(before?.neighbors ?? []), ...(after?.neighbors ?? [])].some(id => id !== null && changed.has(id));
    if (!changed.has(unitId) && !changedNeighbor && before?.previous === after?.previous && before?.next === after?.next && before?.open === after?.open) continue;
    if (!after) return "unresolved-ownership";
    if (!reading) return "unknown-reading";
    if (reading.kind === "unsupported-construction") return "construction-obligation";
    if (reading.kind === "following-letter") {
      if (reading.require && !reading.require.includes(after.next)) return "construction-obligation";
      if (reading.forbid?.includes(after.next)) return "construction-obligation";
    }
    if (reading.kind === "open-vowel-or-split-marker") {
      const slot = choices[unitId].slot;
      // Generic silent-e ancestry cannot certify a split marker. Open realization
      // requires both the phone structure and the final exact written part to be open.
      if (slot.position !== "nucleus" || slot.codaLength !== 0 || !after.open) return "construction-obligation";
    }
  }
  return undefined;
}

/** Prefix state after `choices[index]` takes `option`, rolled over when its syllable ends. */
function nextPrefix(state: GraphemePrefixState, choices: SpellingChoiceState[], index: number, option: Option): GraphemePrefixState {
  const choice = choices[index];
  const advanced = advanceGraphemePrefix(state, choice.slot.position, option.grapheme.form, option.form, option.countIncrement);
  return choices[index + 1]?.slot.syllableIndex === choice.slot.syllableIndex ? advanced : rollGraphemePrefixSyllable(advanced);
}

function hasInvalidJunction(choices: SpellingChoiceState[], config: LanguageConfig): boolean {
  const syllableCount = choices[0]?.slot.syllableCount ?? 0;
  for (let i = 0; i < syllableCount - 1; i++) {
    const coda = choices.filter(choice => choice.slot.syllableIndex === i && choice.slot.position === "coda").map(choice => choice.slot.phoneme);
    const onset = choices.filter(choice => choice.slot.syllableIndex === i + 1 && choice.slot.position === "onset").map(choice => choice.slot.phoneme);
    if (coda.length && onset.length && !validateJunction(coda, onset, config)) return true;
  }
  return false;
}

/** Deterministic constrained search. Selection RNG is never called here. */
/**
 * Visited partial assignments before a plan search gives up. Successful respells
 * visit 28 on average (at most 924 in 200k words); failed searches would
 * otherwise run to the limit, so it bounds the cost of words that cannot be fixed.
 */
export const SPELLING_COVERAGE_SEARCH_LIMIT = 2048;

export function createSpellingCoveragePlanner(
  config: LanguageConfig,
  resolve = createGraphemeResolver(config),
  doubling = createDoublingModel(config.doubling),
) {
  const inventory = new Map(config.graphemes.map((grapheme, i) => [grapheme, i]));
  const constraints = config.writtenFormConstraints;

  function optionsFor(choice: SpellingChoiceState, unitId: number, prefix: GraphemePrefixState): Option[] {
    const pool = resolve(choice.slot, prefix);
    const total = pool.weights.reduce((sum, [, weight]) => sum + weight, 0);
    const options: Option[] = [];
    for (const [grapheme, weight] of pool.weights) {
      const decision = doubling.describe({ ...choice.doubling, form: grapheme.form,
        nucleusForm: doublingNucleusForm(prefix, choice.slot.position, grapheme.form) }, prefix.doublingCount);
      const outcomes = decision.kind === "fixed"
        ? [{ form: decision.form, probability: 1, countIncrement: decision.countIncrement }]
        : [
          ...(decision.probability < 100 ? [{ form: decision.form, probability: 1 - decision.probability / 100, countIncrement: 0 }] : []),
          { form: decision.doubledForm, probability: decision.probability / 100, countIncrement: 1 },
        ];
      for (const outcome of outcomes) options.push({ grapheme, form: outcome.form, countIncrement: outcome.countIncrement,
        reading: doubling.readingFor(grapheme, outcome.form),
        license: { unitId, inventoryIndex: inventory.get(grapheme) ?? -1, selected: grapheme.form, afterDoubling: outcome.form,
          graphemeProbability: weight / total, doublingProbability: outcome.probability,
          pool: pool.fallback ? "fallback" : "ordinary", quotaRelaxed: !!pool.preferenceRelaxed } });
    }
    // The original realization is visited first; all other ties retain inventory/outcome order.
    return options.sort((a, b) => Number(b.grapheme === choice.grapheme && b.form === choice.form) - Number(a.grapheme === choice.grapheme && a.form === choice.form));
  }

  const contextsFor = (choices: SpellingChoiceState[]) => choices.map(choice => ({
    slot: choice.slot, doubling: choice.doubling, inventoryIndex: inventory.get(choice.grapheme) ?? -1, afterDoubling: choice.form,
  }));

  /** Recompute every license and final reading; caller-provided probabilities are not trusted. */
  function verify(base: Pick<BaseSpelling, "current">, choices: SpellingChoiceState[], plan: Omit<SpellingCoverageCertificate, "id">): void {
    const fail = (): never => { throw new Error("Invalid spelling coverage certificate"); };
    const equal = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b);
    if (plan.version !== 1 || plan.choices.length !== choices.length || !equal(plan.contexts, contextsFor(choices)) || hasInvalidJunction(choices, config)) fail();
    const state = base.current();
    if (!equal(plan.inputCellIds, state.cells.map(cell => cell.id)) ||
        plan.before !== state.cells.map(cell => cell.text).join("")) fail();
    const spans = unitSpans(state.cells, choices);
    const options: Option[] = [];
    const changed = new Set<number>();
    let prefix = INITIAL_GRAPHEME_PREFIX;
    let score = 0;
    for (const [i, choice] of choices.entries()) {
      const option = optionsFor(choice, i, prefix)
        .find(candidate => equal(candidate.license, plan.choices[i]));
      if (!option) fail();
      const selected = option!;
      if (selected.grapheme !== choice.grapheme || selected.form !== choice.form) {
        if (!spans.has(i)) fail();
        changed.add(i);
      }
      options.push(selected);
      prefix = nextPrefix(prefix, choices, i, selected);
      score = score + Math.log(selected.license.graphemeProbability) + Math.log(selected.license.doublingProbability);
    }
    const original = project(state.cells, spans, new Map());
    const proposed = project(state.cells, spans, new Map([...changed].map(i => [i, options[i].form])));
    const after = proposed.map(cell => cell.text).join("");
    const budgets = measureSpellingBudgets(after, constraints);
    if (!changed.size || checkReadings(original, proposed, choices, options, changed) ||
        after !== plan.after || score !== plan.logProbability || !equal(plan.budgets, budgets) || budgets.exceeded.length) fail();
    const replacements = [...changed].map(unitId => ({
      unitId, phoneIds: [...state.units[unitId].phoneIds], partId: spans.get(unitId)!.partId,
      inputCellIds: spans.get(unitId)!.cells.map(cell => cell.id), before: choices[unitId].form,
      after: options[unitId].form, reading: options[unitId].reading!,
    }));
    if (!equal(plan.replacements, replacements) || !equal(plan.phoneIds, replacements.flatMap(entry => entry.phoneIds))) fail();
  }

  function apply(base: BaseSpelling, choices: SpellingChoiceState[], scope: SpellingBudgetOutcome["scope"], invalidJunction = hasInvalidJunction(choices, config)): SpellingBudgetOutcome {
    const state = base.current();
    const surface = state.cells.map(cell => cell.text).join("");
    const before = measureSpellingBudgets(surface, constraints);
    const common = { version: 1 as const, scope, before, after: before, visitedAssignments: 0, legalOptions: 0,
      unresolvedCells: state.cells.filter(cell => cell.origin.kind === "rewrite").length, changedUnits: [] as number[] };
    if (!invalidJunction && before.exceeded.length === 0) return { ...common, status: "satisfied" };
    const refuse = (reason: SpellingBudgetRefusal, refusals: Partial<Record<SpellingBudgetRefusal, number>>): SpellingBudgetOutcome =>
      ({ ...common, status: "infeasible", reason, refusals });
    if (invalidJunction) return refuse("invalid-junction", { "invalid-junction": 1 });
    if (!base.projectParts(choices[0]?.slot.syllableCount ?? 0)) return refuse("unresolved-ownership", { "unresolved-ownership": 1 });
    const spans = unitSpans(state.cells, choices);
    const originalCells = project(state.cells, spans, new Map());
    const unresolvedParts = new Set(originalCells.filter(cell => cell.unitId === null).map(cell => cell.partId));
    const refusals: Partial<Record<SpellingBudgetRefusal, number>> = {};
    const note = (reason: SpellingBudgetRefusal): void => { refusals[reason] = (refusals[reason] ?? 0) + 1; };
    const selected: Option[] = [];
    const changed = new Set<number>();
    let best: { plan: Omit<SpellingCoverageCertificate, "id">; options: Option[] } | undefined;
    let exhausted = false;

    function evaluate(score: number): void {
      const changes = new Map([...changed].map(id => [id, selected[id].form]));
      const cells = project(state.cells, spans, changes);
      const after = cells.map(cell => cell.text).join("");
      const budgets = measureSpellingBudgets(after, constraints);
      if (budgets.exceeded.length) return;
      const readingRefusal = checkReadings(originalCells, cells, choices, selected, changed);
      if (readingRefusal) { note(readingRefusal); return; }
      const replacements: SpellingUnitReplacement[] = [...changed].sort((a, b) => a - b).map(unitId => ({
        unitId, phoneIds: [...state.units[unitId].phoneIds], partId: spans.get(unitId)!.partId,
        inputCellIds: spans.get(unitId)!.cells.map(cell => cell.id), before: choices[unitId].form,
        after: selected[unitId].form, reading: selected[unitId].reading!,
      }));
      const plan: Omit<SpellingCoverageCertificate, "id"> = {
        version: 1, inputCellIds: state.cells.map(cell => cell.id), before: surface, after, replacements,
        choices: selected.map(option => ({ ...option.license })), contexts: structuredClone(contextsFor(choices)), phoneIds: replacements.flatMap(replacement => replacement.phoneIds),
        logProbability: score, budgets,
      };
      if (!best || score > best.plan.logProbability + 1e-12) best = { plan, options: selected.slice() };
    }

    function search(index: number, remaining: number, prefix: GraphemePrefixState, score: number): void {
      if (exhausted) return;
      if (common.visitedAssignments >= SPELLING_COVERAGE_SEARCH_LIMIT) { exhausted = true; return; }
      common.visitedAssignments++;
      // Count the assigned state before rejecting a fixed impossibility. Remaining
      // choices cannot supply a missing reading or an owned marker to this unit.
      if (changed.has(index - 1)) {
        const choice = choices[index - 1];
        const reading = selected[index - 1].reading;
        if (unresolvedParts.has(choice.slot.syllableIndex)) { note("unresolved-ownership"); return; }
        if (!reading) { note("unknown-reading"); return; }
        if (reading.kind === "unsupported-construction" ||
            (reading.kind === "open-vowel-or-split-marker" && choice.slot.codaLength > 0)) {
          note("construction-obligation"); return;
        }
      }
      if (index === choices.length) { if (remaining === 0) evaluate(score); return; }
      if (remaining > choices.length - index) return;
      let options: Option[];
      try { options = optionsFor(choices[index], index, prefix); }
      catch (error) { if (error instanceof NoLegalGraphemeError) { note("no-licensed-plan"); return; } throw error; }
      common.legalOptions += options.length;
      for (const option of options) {
        const choice = choices[index];
        const isChanged = option.grapheme !== choice.grapheme || option.form !== choice.form;
        if (isChanged && remaining === 0) continue;
        if (isChanged && !spans.has(index)) { note("unresolved-ownership"); continue; }
        if (option.license.inventoryIndex < 0) { note("unknown-reading"); continue; }
        selected[index] = option;
        if (isChanged) changed.add(index);
        search(index + 1, remaining - Number(isChanged), nextPrefix(prefix, choices, index, option),
          score + Math.log(option.license.graphemeProbability) + Math.log(option.license.doublingProbability));
        if (isChanged) changed.delete(index);
        if (exhausted) return;
      }
    }

    for (let changes = 1; changes <= spans.size; changes++) {
      search(0, changes, INITIAL_GRAPHEME_PREFIX, 0);
      if (exhausted) return refuse("search-budget", { ...refusals, "search-budget": 1 });
      if (best) {
        verify(base, choices, best.plan);
        const certificateId = base.commitLicensedPlan(best.plan);
        best.options.forEach((option, i) => { choices[i].grapheme = option.grapheme; choices[i].form = option.form; });
        return { ...common, status: "respell", certificateId, logProbability: best.plan.logProbability,
          after: best.plan.budgets, changedUnits: best.plan.replacements.map(replacement => replacement.unitId) };
      }
    }
    const reasons: SpellingBudgetRefusal[] = ["unresolved-ownership", "unknown-reading", "construction-obligation"];
    const reason = reasons.find(reason => refusals[reason]) ?? "no-licensed-plan";
    return refuse(reason, { ...refusals, "no-licensed-plan": 1 });
  }
  return { apply, verify };
}

import type { Phoneme, Grapheme, GraphemeReading } from "../types.js";
import type { DoublingConfig, DoublingRealization } from "../config/language.js";
import type { RNG } from "../utils/random.js";
import { VOWEL_LETTERS } from "../utils/letters.js";
import { copyGraphemeReading } from "../elements/graphemes/reading.js";

export interface DoublingState {
  doublingCount: number;
}

export interface DoublingTraceInfo {
  attempted: boolean;
  reason?: string;
  probability?: number;
  result?: string;
}

/** Per-phoneme context for the doubling decision. */
export interface DoublingSlot {
  form: string;
  phoneme: Phoneme;
  position: "onset" | "nucleus" | "coda";
  prevPhoneme?: Phoneme;
  nextNucleus?: Phoneme;
  nucleusForm: string;
  stress?: string;
  prevReduced: boolean;
  isCluster: boolean;
  isFirstInCoda: boolean;
  isLastPhoneme: boolean;
  isEndOfWord: boolean;
  isMonosyllabic: boolean;
  nextIsConsonant: boolean;
}

/** Pure transition description; probability is present exactly when the sampler draws. */
export type DoublingDecision =
  | { kind: "fixed"; form: string; reason: string; countIncrement: number }
  | { kind: "probabilistic"; form: string; probability: number; doubledForm: string };

function validReading(reading: GraphemeReading): boolean {
  if (!reading || typeof reading !== "object") return false;
  switch (reading.kind) {
  case "single-phone":
  case "open-vowel-or-split-marker": return true;
  case "unsupported-construction": return typeof reading.reason === "string";
  case "following-letter": return [reading.require, reading.forbid].every(letters =>
    letters === undefined || (Array.isArray(letters) && letters.every(letter => typeof letter === "string" && letter.length === 1)));
  default: return false;
  }
}

function realizationLookup(rules: readonly DoublingRealization[] | undefined) {
  if (rules === undefined) return undefined;
  const lookup = new Map<string, Map<string, DoublingRealization>>();
  for (const rule of rules) {
    if (typeof rule.phoneme !== "string" || !rule.phoneme || typeof rule.from !== "string" || rule.from.length !== 1 ||
        typeof rule.to !== "string" || rule.to.length < 2 || lookup.get(rule.phoneme)?.has(rule.from) || !validReading(rule.reading) ||
        (rule.allowInCodaCluster !== undefined && typeof rule.allowInCodaCluster !== "boolean")) {
      throw new Error("Invalid or duplicate doubling realization");
    }
    const forms = lookup.get(rule.phoneme) ?? new Map<string, DoublingRealization>();
    forms.set(rule.from, { ...rule, reading: copyGraphemeReading(rule.reading) });
    lookup.set(rule.phoneme, forms);
  }
  return lookup;
}

export function createDoublingModel(config: DoublingConfig | undefined) {
  const enabled = !!config?.enabled;
  const realizations = realizationLookup(config?.realizations);
  const directForms = new Map<string, Set<string>>();
  for (const [sound, forms] of realizations ?? []) {
    directForms.set(sound, new Set([...forms.values()].map(rule => rule.to)));
  }

  /** Reading of the realized unit, independently of the selected spelling's obligation. */
  function readingFor(grapheme: Grapheme, realized: string): GraphemeReading | undefined {
    if (!realizations || realized === grapheme.form) return grapheme.reading;
    const rule = realizations.get(grapheme.phoneme)?.get(grapheme.form);
    return rule?.to === realized ? copyGraphemeReading(rule.reading) : undefined;
  }
  const neverDoubleSet = new Set(config?.neverDouble ?? []);
  const doubledFormSet = new Set(Object.values(config?.doubledForms ?? {}));
  const neverDoubleAfterSet = new Set<string>(enabled ? config?.neverDoubleAfter ?? [] : []);
  const doubledFormLookup = config?.doubledForms ?? {};
  const hasDirectForms = realizations ? directForms.size > 0 : doubledFormSet.size > 0;
  function isDirectForm(sound: string, form: string): boolean {
    return realizations ? !!directForms.get(sound)?.has(form) : doubledFormSet.has(form);
  }
  function describe(slot: DoublingSlot, doublingCount: number): DoublingDecision {
    if (!enabled || !config) return { kind: "fixed", form: slot.form, reason: "disabled", countIncrement: 0 };
    const {
      form, phoneme, position, prevPhoneme, nextNucleus, nucleusForm,
      stress, prevReduced, isCluster, isFirstInCoda,
      isLastPhoneme, isEndOfWord, isMonosyllabic, nextIsConsonant,
    } = slot;

    const skip = (reason: string, countIncrement = 0): DoublingDecision => ({ kind: "fixed", form, reason, countIncrement });

    if (!prevPhoneme) return skip("no-prev-phoneme");
    const realization = realizations?.get(phoneme.sound)?.get(form);
    const clusterAllowed = realizations ? realization?.allowInCodaCluster : !!doubledFormLookup[form];

    // Only explicitly permitted spellings (legacy: custom overrides) enter coda clusters.
    if (isCluster && !(position === "coda" && isFirstInCoda && clusterAllowed)) return skip("in-cluster");

    // Suppress doubling when a coda consonant is followed by another consonant (onset of next syllable).
    // Doubling here creates impossible cross-syllable clusters: "nn" + "t" → "nnt", "ll" + "d" → "lld".
    if (position === "coda" && nextIsConsonant) return skip("coda-before-consonant");

    if (form.length !== 1) {
      // Directly selected doubled forms count only after the preceding eligibility guards.
      return skip("multi-char-grapheme", isDirectForm(phoneme.sound, form) ? 1 : 0);
    }
    if (position !== "onset" && position !== "coda") return skip("nucleus-position");
    if (doublingCount >= config.maxPerWord) return skip("max-per-word");

    // Phonological trigger
    if (config.trigger === "lax-vowel") {
      const isAfterVowel = prevPhoneme.nucleus != null && prevPhoneme.nucleus > 0;
      const isLax = prevPhoneme.tense === false;
      if (!isAfterVowel || !isLax) return skip("trigger:not-after-lax-vowel");
    }

    // Doubling signals "short vowel" to the reader — but only works when the
    // nucleus *looks like* a vowel on the page. Vowel graphemes that end in a
    // consonant letter (e.g. /ɚ/ → "er"/"or"/"ur") break the visual signal:
    // "erss" reads as a consonant pileup, not doubled-after-short-vowel.
    // Empty on first-syllable onset (no preceding nucleus) — the lax-vowel
    // trigger above already rejects that case.
    if (nucleusForm.length > 0) {
      const lastNucleusChar = nucleusForm[nucleusForm.length - 1].toLowerCase();
      if (!VOWEL_LETTERS.has(lastNucleusChar)) return skip("nucleus-ends-consonant-letter");
    }
    if (neverDoubleAfterSet.has(nucleusForm)) return skip("never-double-after");

    // neverDoubleFinal — suppress word-final doubling for specific sounds
    if (isEndOfWord && isLastPhoneme && config.neverDoubleFinal?.includes(phoneme.sound)) return skip("never-double-final");

    // neverDouble — check both phoneme sound and grapheme form
    if (neverDoubleSet.has(phoneme.sound)) return skip("never-double:sound");
    if (neverDoubleSet.has(form)) return skip("never-double:form");

    // finalDoublingOnly
    if (isEndOfWord && config.finalDoublingOnly && config.finalDoublingOnly.length > 0) {
      if (!config.finalDoublingOnly.includes(phoneme.sound)) return skip("final-doubling-only");
    }

    // suppressAfterReduction
    if (config.suppressAfterReduction && prevReduced) return skip("suppress-after-reduction");

    // suppressBeforeTense
    if (config.suppressBeforeTense && nextNucleus) {
      if (nextNucleus.tense === true) return skip("suppress-before-tense");
    }

    if (realizations && !realization) return skip("unsupported-realization");

    // Calculate probability
    let prob = config.probability;
    // Monosyllables are inherently stressed even without a ˈ marker.
    // Only apply unstressed modifier to genuinely unstressed syllables in polysyllabic words.
    if (config.unstressedModifier != null && !stress && !isMonosyllabic) {
      prob *= config.unstressedModifier;
    }
    prob = Math.min(100, Math.max(0, Math.round(prob)));
    if (prob <= 0) return skip("zero-probability:unstressed");

    return { kind: "probabilistic", form, probability: prob, doubledForm: realization?.to ?? doubledFormLookup[form] ?? (form + form) };
  }

  function sample(slot: DoublingSlot, state: DoublingState, rand: RNG, trace?: DoublingTraceInfo): string {
    const decision = describe(slot, state.doublingCount);
    if (decision.kind === "fixed") {
      state.doublingCount += decision.countIncrement;
      if (trace) { trace.attempted = false; trace.reason = decision.reason; }
      return decision.form;
    }
    // Keep the legacy draw even at 100%; pure planning never calls this wrapper.
    const shouldDouble = rand() * 100 < decision.probability;
    if (shouldDouble) {
      state.doublingCount++;
      if (trace) { trace.attempted = true; trace.probability = decision.probability; trace.result = decision.doubledForm; }
      return decision.doubledForm;
    }
    if (trace) { trace.attempted = true; trace.probability = decision.probability; trace.reason = "roll-failed"; }
    return decision.form;
  }
  return { describe, sample, readingFor, isDirectForm, hasDirectForms };
}

import { spellingBoundaryContexts } from "./spelling-context.js";
import type { LanguageConfig } from "../config/language.js";
import type { BaseSpellingTrace, SpellingCell } from "./base-spelling.js";
import { createSpellingCoveragePlanner } from "./spelling-coverage.js";

/** Exact ledger replay. V1 has no available part identity or licensed replacement capability. */
export function createBaseSpellingEvidenceVerifier(config?: LanguageConfig) {
  const planner = config ? createSpellingCoveragePlanner(config) : undefined;
  return (trace: BaseSpellingTrace): { version: 1 | 2; verifiedCertificates: number } => {
    const require = (condition: unknown, message: string): void => { if (!condition) throw new Error(`Invalid spelling evidence: ${message}`); };
    const equal = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b);
    require(trace.version === 1 || trace.version === 2, "unsupported ledger version");
    const licensed = trace.version === 2;
    require(!licensed || equal(trace.capabilities, { exactParts: 1, licensedOrigins: 1, writerBoundary: 1 }), "unsupported capabilities");
    require(licensed || (trace.capabilities === undefined && trace.certificates === undefined), "v1 cannot declare v2 capabilities");
    require(trace.phones.length === trace.units.length, "phone/unit cardinality");
    const boundaryContexts = licensed ? spellingBoundaryContexts(trace.phones) : undefined;
    const priorChoices = trace.units.map(unit => ({ inventoryIndex: unit.inventoryIndex, afterDoubling: unit.afterDoubling }));
    const knownIds = new Set<number>();
    const cells: SpellingCell[] = [];
    for (const [i, unit] of trace.units.entries()) {
      require(unit.id === i && unit.choiceId === i && equal(unit.phoneIds, [i]), "unit/phone identity");
      require(unit.sourceCellIds.length === unit.afterDoubling.length, "source-cell length");
      require(trace.phones[i]?.id === i, "phone identity");
      if (licensed) {
        require(Number.isInteger(unit.inventoryIndex) && unit.inventoryIndex! >= 0, "selection inventory identity");
        if (config) {
          const selected = config.graphemes[unit.inventoryIndex!];
          require(selected?.form === unit.selected && selected.phoneme === trace.phones[i].soundAtSpelling, "selected inventory identity");
        }
      }
      unit.sourceCellIds.forEach((id, offset) => {
        require(!knownIds.has(id), "reused source ID"); knownIds.add(id);
        cells.push({ id, text: unit.afterDoubling[offset], origin: { kind: "selection", unitId: i, offset },
          ...(licensed ? { partId: trace.phones[i].syllableIndex } : {}) });
      });
    }
    const verified = new Set<number>();
    for (const [i, edit] of trace.edits.entries()) {
      require(edit.id === i && Number.isInteger(edit.start) && edit.start >= 0, "edit identity/range");
      require(equal(cells.slice(edit.start, edit.start + edit.input.length), edit.input), "edit input cells");
      require(edit.before === edit.input.map(cell => cell.text).join("") && edit.after === edit.output.map(cell => cell.text).join(""), "edit text");
      if (licensed) {
        require(edit.partId === null || Number.isInteger(edit.partId), "missing edit part identity");
        const parts = new Set(edit.input.map(cell => cell.partId));
        const expectedPart = parts.size === 1 ? edit.input[0].partId : null;
        if (edit.input.length) require(edit.partId === expectedPart, "edit part disagrees with consumed cells");
        require(edit.output.every(cell => cell.partId === edit.partId), "output part disagrees with edit");
      }
      const sources = [...new Set(edit.input.flatMap(cell => cell.origin.kind === "rewrite" ? cell.origin.sourceUnitIds : [cell.origin.unitId]))];
      for (const [offset, cell] of edit.output.entries()) {
        require(!knownIds.has(cell.id) && cell.text.length === 1, "output cell identity/length"); knownIds.add(cell.id);
        if (cell.origin.kind === "licensed") {
          const origin = cell.origin;
          require(licensed && !!planner && !!config, "licensed replay requires v2 and its config");
          const certificate = trace.certificates?.[cell.origin.certificateId];
          require(certificate?.id === cell.origin.certificateId && certificate.version === 1, "certificate identity/version");
          if (!certificate || !config || !planner) throw new Error("Missing certificate inputs");
          if (!verified.has(certificate.id)) {
            require(certificate.contexts.length === trace.units.length, "certificate context count");
            const choices = certificate.contexts.map((context, id) => {
              const expected = boundaryContexts![id];
              require(equal(context.slot, expected.slot) && equal(context.doubling, expected.doubling), "authoritative writer-boundary context");
              require(context.inventoryIndex === priorChoices[id].inventoryIndex && context.afterDoubling === priorChoices[id].afterDoubling, "pre-plan choice state");
              const slot = expected.slot;
              const grapheme = config.graphemes[context.inventoryIndex];
              require(grapheme?.phoneme === slot.phoneme.sound, "inventory identity");
              return { ...expected, grapheme, form: context.afterDoubling };
            });
            planner.verify({ current: () => ({ cells, units: trace.units, phones: trace.phones }) }, choices, certificate);
            certificate.choices.forEach((choice, id) => { priorChoices[id] = { inventoryIndex: choice.inventoryIndex, afterDoubling: choice.afterDoubling }; });
            verified.add(certificate.id);
          }
          const replacement = certificate.replacements.find(entry => entry.unitId === origin.unitId);
          require(!!replacement && equal(replacement.inputCellIds, edit.input.map(entry => entry.id)) &&
          replacement.after === edit.after && cell.text === replacement.after[cell.origin.offset] &&
          cell.partId === replacement.partId && cell.origin.editId === edit.id && cell.origin.offset === offset &&
          equal(cell.origin.sourceUnitIds, [cell.origin.unitId]), "licensed edit/certificate mismatch");
        } else {
          require(cell.origin.kind === "rewrite" && cell.origin.editId === edit.id && equal(cell.origin.sourceUnitIds, sources) &&
          cell.origin.ownership === "unresolved", "rewrite ancestry is not ownership");
          require(!licensed || cell.partId === null || Number.isInteger(cell.partId), "missing v2 part identity");
        }
        require(licensed || cell.partId === undefined, "v1 part identity unavailable");
      }
      cells.splice(edit.start, edit.input.length, ...edit.output);
    }
    require(equal(cells, trace.cells) && cells.map(cell => cell.text).join("") === trace.surface, "final cells/surface");
    require(trace.unresolvedCells === cells.filter(cell => cell.origin.kind === "rewrite").length, "unresolved count");
    require(verified.size === (trace.certificates?.length ?? 0), "certificate without an applied edit");
    return { version: trace.version, verifiedCertificates: verified.size };
  };
}

export function verifyBaseSpellingEvidence(trace: BaseSpellingTrace, config?: LanguageConfig): { version: 1 | 2; verifiedCertificates: number } {
  return createBaseSpellingEvidenceVerifier(config)(trace);
}

import { Phoneme, Syllable, WordGenerationContext } from "../types.js";
import { StressRules } from "../config/language.js";
import getWeightedOption from "../utils/getWeightedOption.js";
import { isNucleusWordPositionAllowed, nucleusWordEdges } from "./nucleus-position.js";
import { isNucleusCompatibleWithCoda, isNucleusCompatibleWithFollowingOnset } from "./rime-compatibility.js";
import type { BannedNucleusCodaPairs } from "./rime-compatibility.js";

/**
 * After stress assignment, re-pick any nucleus whose sound is banned under
 * primary stress (e.g. schwa /ə/ should not carry primary stress in English).
 *
 * Lexical monosyllables carry internal primary stress even when their IPA
 * display omits the stress mark. They obey the same nucleus restrictions.
 */
export function repairStressedNuclei(
  context: WordGenerationContext,
  nucleusPhonemes: Phoneme[],
  stress: StressRules,
  bannedPairs?: BannedNucleusCodaPairs,
  retainedRoot?: { syllables: readonly Syllable[]; start: number },
  followingOnsetPairs?: BannedNucleusCodaPairs,
): void {
  const ban = stress.nucleus.stressedNucleusBan;
  if (!ban || ban.length === 0) return;

  const banSet = new Set(ban);

  // Pre-filter the pool once — remove banned sounds
  const allowed = nucleusPhonemes.filter(p => !banSet.has(p.sound));

  const weightedAllowed: [Phoneme, number][] = allowed.map(p => [p, p.nucleus ?? 1]);

  for (const [syllableIndex, syllable] of context.word.syllables.entries()) {
    if (syllable.stress !== "ˈ") continue;

    const nucleus = syllable.nucleus[0];
    if (!nucleus || !banSet.has(nucleus.sound)) continue;

    // Final stress operates on the assembled word, but only root replacements
    // are copied back before root spelling. Keep affix legality out of this rule.
    const rootIndex = syllableIndex - (retainedRoot?.start ?? 0);
    const rootSyllable = retainedRoot ? retainedRoot.syllables[rootIndex] : syllable;
    const coda = rootSyllable?.coda ?? syllable.coda;
    const pairRules = rootSyllable ? bannedPairs : undefined;
    // Only a following root syllable counts; affix joins are exempt.
    const nextOnset = retainedRoot ? retainedRoot.syllables[rootIndex + 1]?.onset : context.word.syllables[syllableIndex + 1]?.onset;
    const onsetRules = rootSyllable ? followingOnsetPairs : undefined;
    const before = nucleus.sound;
    const edges = nucleusWordEdges(syllable, syllableIndex, context.word.syllables.length, 0);
    const eligible: [Phoneme, number][] = [];
    let positivePairExclusions = 0;
    let totalWeight = 0;
    for (const [phoneme, weight] of weightedAllowed) {
      if (!Number.isFinite(weight) || weight <= 0 || !isNucleusWordPositionAllowed(phoneme, edges)) continue;
      if (!isNucleusCompatibleWithCoda(phoneme.sound, coda, pairRules)
        || !isNucleusCompatibleWithFollowingOnset(phoneme.sound, coda, nextOnset, onsetRules)) {
        positivePairExclusions++;
        continue;
      }
      eligible.push([phoneme, weight]);
      totalWeight += weight;
    }
    if (eligible.length === 0 || !Number.isFinite(totalWeight)) {
      throw new Error("No eligible stressed nucleus with finite positive weight for the realized lexical-root position and retained coda.");
    }
    syllable.nucleus[0] = getWeightedOption(eligible, context.rand);
    context.trace?.recordRepair(retainedRoot ? "repairFinalStressedNuclei" : "repairStressedNuclei", before, syllable.nucleus[0].sound,
      `replaced banned stressed nucleus /${before}/`, rootSyllable ? {
        domain: "lexical-root", syllableIndex: rootIndex, nucleusIndex: 0,
        coda: coda.map(phoneme => phoneme.sound), edges, weighting: "nucleus-only",
        eligibleCandidateEntries: eligible.length, positivePairExclusions, totalWeight,
      } : undefined);
  }

  // Future: unstressedNucleusBoost — config is read but no behaviour change yet
  // const _boost = stress.nucleus.unstressedNucleusBoost;
}

import type { Phoneme, Syllable } from "../types.js";
import type { PrimaryStressRules } from "../config/language.js";

/** Model-qualified phonological contribution, not a prediction of duration. */
export interface NuclearQuantity {
  analysis: string;
  moras: 1 | 2;
}

export type SyllableWeightPolicy =
  | { type: "legacy-segment-count" }
  | {
      type: "moraic";
      analysis: string;
      coda: "weight-by-position" | "nonmoraic";
      unknown: "legacy-segment-count" | "error";
    };

export const LEGACY_SYLLABLE_WEIGHT: SyllableWeightPolicy = { type: "legacy-segment-count" };

export interface NuclearQuantityObservation {
  segmentIndex: number;
  sound: string;
  declared?: NuclearQuantity;
  quantity:
    | { status: "known"; moras: 1 | 2 }
    | { status: "unknown"; reason: "unspecified" | "model-mismatch" | "legacy-policy" };
}

export interface SyllableWeightAnalysis {
  syllableIndex: number;
  nucleus: NuclearQuantityObservation[];
  /** Exact sum only when every contribution belongs to the selected model. */
  nucleusMoras: number | null;
  coda: string[];
  analytical: {
    weight: "light" | "heavy" | "unknown";
    basis: "nuclear-quantity" | "weight-by-position" | "unspecified-quantity" | "empty-nucleus" | "legacy-policy";
  };
  operational: {
    weight: "light" | "heavy";
    basis: "legacy-rule" | "moraic-analysis" | "legacy-fallback";
  };
}

export interface StressWeightTrace {
  version: 1;
  stage: "applyStress";
  domain: "root-before-nucleus-repair";
  policy: SyllableWeightPolicy;
  syllables: SyllableWeightAnalysis[];
  primary: { strategy: PrimaryStressRules["type"]; selectedIndex: number | null };
  secondary: {
    /** Candidate choice and application before the separate rhythmic pass. */
    candidates: Array<{ syllableIndex: number; weight: number }>;
    selectedIndex: number | null;
    applied: boolean;
  };
}

function observeQuantity(phone: Phoneme, segmentIndex: number, policy: SyllableWeightPolicy): NuclearQuantityObservation {
  const declared = phone.nuclearQuantity ? { ...phone.nuclearQuantity } : undefined;
  let quantity: NuclearQuantityObservation["quantity"];
  if (!declared) quantity = { status: "unknown", reason: "unspecified" };
  else if (policy.type === "legacy-segment-count") quantity = { status: "unknown", reason: "legacy-policy" };
  else if (declared.analysis !== policy.analysis) quantity = { status: "unknown", reason: "model-mismatch" };
  else quantity = { status: "known", moras: declared.moras };
  return { segmentIndex, sound: phone.sound, declared, quantity };
}

function analyticalWeight(
  syllable: Syllable,
  policy: SyllableWeightPolicy,
  knownMoras: number,
  complete: boolean,
): SyllableWeightAnalysis["analytical"] {
  if (policy.type === "legacy-segment-count") return { weight: "unknown", basis: "legacy-policy" };
  if (syllable.nucleus.length === 0) return { weight: "unknown", basis: "empty-nucleus" };
  if (syllable.coda.length > 0 && policy.coda === "weight-by-position") return { weight: "heavy", basis: "weight-by-position" };
  if (knownMoras >= 2) return { weight: "heavy", basis: "nuclear-quantity" };
  if (complete) return { weight: "light", basis: "nuclear-quantity" };
  return { weight: "unknown", basis: "unspecified-quantity" };
}

function operationalWeight(
  syllable: Syllable,
  syllableIndex: number,
  policy: SyllableWeightPolicy,
  analytical: SyllableWeightAnalysis["analytical"],
): SyllableWeightAnalysis["operational"] {
  const legacyWeight = syllable.coda.length > 0 || syllable.nucleus.length > 1 ? "heavy" : "light";
  if (policy.type === "legacy-segment-count") return { weight: legacyWeight, basis: "legacy-rule" };
  if (analytical.weight !== "unknown") return { weight: analytical.weight, basis: "moraic-analysis" };
  if (policy.unknown === "legacy-segment-count") return { weight: legacyWeight, basis: "legacy-fallback" };
  throw new Error(`Unknown syllable weight in analysis "${policy.analysis}" at syllable ${syllableIndex}: ${analytical.basis}`);
}

export function analyzeSyllableWeight(
  syllable: Syllable,
  syllableIndex: number,
  policy: SyllableWeightPolicy = LEGACY_SYLLABLE_WEIGHT,
): SyllableWeightAnalysis {
  const nucleus = syllable.nucleus.map((phone, index) => observeQuantity(phone, index, policy));
  const knownMoras = nucleus.reduce((total, item) => total + (item.quantity.status === "known" ? item.quantity.moras : 0), 0);
  const complete = nucleus.length > 0 && nucleus.every(item => item.quantity.status === "known");
  const nucleusMoras = complete ? knownMoras : null;
  const analytical = analyticalWeight(syllable, policy, knownMoras, complete);
  const operational = operationalWeight(syllable, syllableIndex, policy, analytical);

  return { syllableIndex, nucleus, nucleusMoras, coda: syllable.coda.map(phone => phone.sound), analytical, operational };
}

export function analyzeWordWeight(
  syllables: Syllable[],
  policy: SyllableWeightPolicy = LEGACY_SYLLABLE_WEIGHT,
): SyllableWeightAnalysis[] {
  return syllables.map((syllable, index) => analyzeSyllableWeight(syllable, index, policy));
}

import type { SpellingBudgetOutcome } from "./spelling-coverage-types.js";
import type { BaseSpellingTrace } from "./base-spelling.js";
import type { Syllable, SyllableShapePlan } from "../types.js";
import type { AcceptanceCriteria, AttemptScore } from "./length-semantics.js";
import type { MorphologyRealizationTrace } from "./morphology/realization.js";
import type { StressWeightTrace } from "./syllable-weight.js";

/** Lengths of a scored root attempt, before any planned affixes are attached. */
export interface AttemptLengths {
  syllables: number;
  phonemes: number;
  letters: number;
}

/** Lengths of a root attempt rejected on its phoneme count before it was spelled. */
export type PrunedAttemptLengths = Omit<AttemptLengths, "letters">;

export interface SelectionTrace {
  status: "accepted" | "fallback";
  /** null means no attempt met an acceptance criterion. */
  acceptedBy: "exact" | "relaxed" | null;
  attemptsExecuted: number;
  /** Zero-based index of the returned attempt, which may precede the final attempt. */
  selectedAttempt: number;
  /** Includes the selected attempt when it was returned as a fallback. */
  rejectedAttempts: number;
  /** Counts rejected attempts failing each condition; reasons can overlap. */
  rejectionReasons: { phonemeTarget: number; letterLength: number; warmup: number };
  criteria: AcceptanceCriteria & { maxAttempts: number };
  selected: AttemptLengths & { score: AttemptScore };
  /**
   * Compact distribution of spelled root proposals; no rejected spelling or Word
   * payloads are retained. Together with `prunedLengths` it covers every attempt.
   */
  proposedLengths: Array<AttemptLengths & { count: number }>;
  /**
   * Root attempts rejected on their phoneme count without being spelled: they
   * missed the phoneme target and could not beat the best attempt so far. They
   * count toward `rejectedAttempts` and `rejectionReasons.phonemeTarget` only.
   */
  prunedLengths: Array<PrunedAttemptLengths & { count: number }>;
}

export interface SyllableSnapshot {
  onset: string[];
  nucleus: string[];
  coda: string[];
  stress?: Syllable["stress"];
  /** Nucleus indices reduced during surface realization. */
  reducedNuclei?: number[];
  /** Segment coordinates aspirated during surface realization. */
  aspirated?: { segment: "onset" | "nucleus" | "coda"; index: number }[];
}

export interface StageSnapshot {
  name: string;
  before: SyllableSnapshot[];
  after: SyllableSnapshot[];
}

export interface DoublingTrace {
  /** Whether doubling was attempted. */
  attempted: boolean;
  /** Why doubling was skipped (if it was). */
  reason?: string;
  /** Final probability used for the doubling roll. */
  probability?: number;
  /** The doubled form that was produced. */
  result?: string;
}

export interface GraphemeTrace {
  /** Stable grapheme-decision index in flattened phoneme order. */
  index: number;
  phoneme: string;
  position: string;
  syllableIndex: number;
  candidates: string[];
  afterCondition: string[];
  afterPosition: string[];
  weights: [string, number][];
  roll: number;
  selected: string;
  /** Grapheme form emitted before later orthographic repairs. */
  emitted: string;
  doubled: boolean;
  /** Selection diagnostics added by the legal-weight writer. Missing means legacy/unobserved. */
  selection?: {
    version: 1;
    positionScope: "segment" | "syllable";
    segmentPosition: "initial" | "medial" | "final" | "isolated";
    syllablePosition: "initial" | "medial" | "final" | "isolated";
    ordinaryCandidates: number;
    afterCondition: number;
    afterPosition: number;
    positiveCandidates: number;
    fallback?: "no-conditioned-candidates" | "no-positional-candidates" | "no-positive-weights";
    preferenceRelaxed?: "doubling-quota" | "never-double-after";
  };
  /** Detailed doubling decision (only present when tracing). */
  doubling?: DoublingTrace;
}

/** A changed nucleus selected during lexical-root stress or edge repair. */
export interface NucleusReplacementTrace {
  domain: "lexical-root";
  syllableIndex: number;
  nucleusIndex: number;
  /** Retained coda at selection time, before later surface/affix processing. */
  coda: string[];
  edges: { initial: boolean; final: boolean };
  weighting: "nucleus-only" | "nucleus-times-word-position";
  eligibleCandidateEntries: number;
  /** Finite positive candidates removed only by configured nucleus/coda pairs (including following-onset rules). */
  positivePairExclusions: number;
  totalWeight: number;
}

export interface RepairTrace {
  /** Which repair function fired. */
  rule: string;
  /** What was there before the repair. */
  before: string;
  /** What it became after the repair. */
  after: string;
  /** Optional detail (e.g. which phoneme was dropped, why). */
  detail?: string;
  nucleusReplacement?: NucleusReplacementTrace;
}

export interface MorphologyTrace {
  template: string;
  /** Planned prefix spelling, before allomorph selection. */
  prefix?: string;
  /** Planned suffix spelling, before allomorph selection. */
  suffix?: string;
  /** Legacy baseline affix syllable count; not a deduction from the root.
   * Selected allomorph counts are in realization, and may differ. */
  syllableReduction: number;
  alternations?: MorphophonemicAlternationTrace[];
  /** Selected forms and written parts; absent in historical traces. */
  realization?: MorphologyRealizationTrace;
}

export interface MorphophonemicAlternationTrace {
  rule: string;
  affix: string;
  boundary: "prefix-root" | "root-suffix";
  soundBefore?: string;
  soundAfter?: string;
  writtenBefore?: string;
  writtenAfter?: string;
}

export interface BoundaryDropTrace {
  event: "boundaryDrop";
  dropped: string;
  beforeOnset: string;
  equalSonority: number;
  probability: number;
  leftSyllableIndex: number;
  rightSyllableIndex: number;
}

export interface RisingCodaBoundaryDropTrace {
  event: "risingCodaBoundaryDrop";
  dropped: string;
