  remainingCoda: string[];
  onset: string[];
  violation: "rule1" | "rule2" | "rule3" | "multi";
  leftSyllableIndex: number;
  rightSyllableIndex: number;
}

export interface JunctionBoundaryDropTrace {
  event: "junctionBoundaryDrop";
  dropped: string;
