    phoneme: "i:", form: "ee", origin: 0, frequency: 3,
    onset: 0, coda: 0, positionScope: "syllable", fallbackOnly: true,
    startWord: 0, midWord: 0, endWord: 0, isolatedSyllableWeight: 1,
