/**
 * Maps IPA phoneme symbols (as used by the word generator) to ARPABET symbols
 * (as used by the CMU Pronouncing Dictionary bigram table).
 *
 * The generator stores phonemes as `Phoneme.sound` strings which may include
 * diacritics like aspiration (ʰ) and stress markers (ˈ, ˌ). This module
 * strips those before mapping.
 *
 * Each phoneme arrives pre-segmented from the generator, so matching is a
 * direct lookup — no substring/greedy parsing required.
 */

import { Phoneme, Word } from "../types.js";

const IPA_TO_ARPABET: Record<string, string> = {
  // Diphthongs
  "eɪ":  "EY",       // day
  "aɪ":  "AY",       // fly
  "əʊ":  "OW",       // globe
  "ɔɪ":  "OY",       // boy
  "aʊ":  "AW",       // cow

  // Affricates
  "tʃ": "CH",        // chat
  "dʒ": "JH",        // judge

  // Vowels
  "i:": "IY",        // sheep (long i)
  "ɪ":  "IH",        // sit
  "e":  "EH",        // red
  "ɛ":  "EH",        // let
  "ə":  "AH",        // the (schwa)
  "ɜ":  "ER",        // bird
  "ɚ":  "ER",        // her
  "æ":  "AE",        // apple
  "ɑ":  "AA",        // father
  "ɔ":  "AO",        // ball
  "o":  "OW",        // hope (GenAm)
  "ʊ":  "UH",        // book
  "u":  "UW",        // blue
  "ʌ":  "AH",        // cup

  // Consonants
  "j":  "Y",
  "w":  "W",
  "l":  "L",
  "r":  "R",
  "m":  "M",
  "n":  "N",
  "ŋ":  "NG",
  "f":  "F",
  "θ":  "TH",
  "h":  "HH",
  "v":  "V",
  "ð":  "DH",
  "z":  "Z",
  "ʒ":  "ZH",
  "s":  "S",
  "ʃ":  "SH",
  "p":  "P",
  "t":  "T",
  "k":  "K",
  "b":  "B",
  "d":  "D",
  "g":  "G",
};

/**
 * Strip diacritics/modifiers from an IPA sound string.
 * Removes aspiration marker (ʰ) since ARPABET doesn't encode it.
 */
function stripDiacritics(sound: string): string {
  return sound.replace(/ʰ/g, "");
}

/**
 * Convert a single IPA phoneme sound string to ARPABET.
 * Returns null if no mapping is found.
 */
export function ipaToArpabet(ipaSound: string): string | null {
  return IPA_TO_ARPABET[stripDiacritics(ipaSound)] ?? null;
}

/**
 * Convert an array of Phoneme objects to a space-separated ARPABET string.
 */
export function phonemesToArpabet(phonemes: Phoneme[]): string {
  return phonemes
    .map((p) => {
      const sound = p.aspirated && !p.sound.endsWith("ʰ") ? `${p.sound}ʰ` : p.sound;
      return ipaToArpabet(sound);
    })
    .filter((a): a is string => a !== null)
    .join(" ");
}

/**
 * Convert a Word's syllables to a single space-separated ARPABET string.
 * Stress markers and syllable boundaries are stripped.
 */
export function wordToArpabet(word: Word): string {
  const allPhonemes: Phoneme[] = [];
  for (const syl of word.syllables) {
    allPhonemes.push(...syl.onset, ...syl.nucleus, ...syl.coda);
  }
  return phonemesToArpabet(allPhonemes);
}

/**
 * Pure TypeScript phonotactic scoring module.
 *
 * Scores ARPABET phoneme sequences using bigram conditional log-probabilities
 * with Laplace smoothing, derived from CMU Pronouncing Dictionary frequencies.
 */

import { ARPABET_BIGRAM_COUNTS, ARPABET_TOTAL_COUNTS, ALL_ARPABET_PHONEMES } from "./arpabet-bigrams.js";

export interface ScoredWord {
  arpabet: string;
  score: number;
  perBigram: number;
}

export interface ScoreStats {
  mean: number;
  min: number;
  median: number;
}

export interface BatchScoreResult {
  words: ScoredWord[];
  total: ScoreStats;
  perBigram: ScoreStats;
}

/**
 * Compute mean, min, and median from an array of numbers.
 */
function computeStats(values: number[]): ScoreStats {
  if (values.length === 0) return { mean: 0, min: 0, median: 0 };
  const sorted = [...values].sort((a, b) => a - b);
  return {
    mean: sorted.reduce((a, b) => a + b, 0) / sorted.length,
    min: sorted[0],
    median: sorted[Math.floor(sorted.length / 2)],
  };
}

/**
 * Conditional log₂-probability of a phoneme bigram with Laplace smoothing.
 *
 *   P(second | first) = (count(first→second) + 1) / (count(first→*) + V)
 */
function bigramLogProb(first: string, second: string): number {
  const counts = ARPABET_BIGRAM_COUNTS[first] || {};
  const vocabSize = ALL_ARPABET_PHONEMES.size;
  return Math.log2(((counts[second] || 0) + 1) / ((ARPABET_TOTAL_COUNTS[first] || 0) + vocabSize));
}

/**
 * Parse an ARPABET string into phoneme tokens, with word-boundary markers.
 * Returns ['#', ...phonemes, '#'], or null if the input is empty.
 */
function parseArpabet(arpabet: string): string[] | null {
  const phonemes = arpabet.trim().split(/\s+/);
  if (phonemes.length === 0 || !phonemes[0]) return null;
  return ["#", ...phonemes, "#"];
}

/**
 * Score a batch of ARPABET transcriptions and return per-word scores plus aggregate stats.
 */
export function scoreArpabetWords(arpabetWords: string[]): BatchScoreResult {
  const words = arpabetWords.map(arpabet => {
    const seq = parseArpabet(arpabet);
    if (!seq) return { arpabet, score: -Infinity, perBigram: -Infinity };

    let score = 0;
    for (let i = 1; i < seq.length; i++) {
      score += bigramLogProb(seq[i - 1], seq[i]);
    }
    const bigramCount = seq.length - 1;
    return { arpabet, score, perBigram: score / bigramCount };
  });

  const finite = (v: number) => isFinite(v) && !isNaN(v);
  return {
    words,
    total: computeStats(words.map(w => w.score).filter(finite)),
    perBigram: computeStats(words.map(w => w.perBigram).filter(finite)),
  };
}

/**
 * Test-only helpers for locating example words by property.
 *
 * Behavior tests must not pin a particular seed or draw index to a particular
 * word: any change to RNG consumption moves every later word. Instead, scan a
 * small, deterministic range of seeds through the public API and take the
 * first word that has the property under test. Exact output is recorded once,
 * in the golden fixture (`npm run golden:update`).
 *
 * Not part of the published build (excluded in tsconfig.json).
 */
import { generateWord } from "../index.js";
import type { Word, WordGenerationOptions } from "../types.js";

/** Anything with the public `generateWord` signature, e.g. `createGenerator(config)`. */
export interface WordSource {
  generateWord(options?: WordGenerationOptions): Word;
}

export interface SeedSearch {
  /** Describes the property in the failure message, e.g. "a b before terminal y". */
  property: string;
  /** Number of consecutive seeds to scan. Keep it a few times the expected gap. */
  limit: number;
  /** First seed scanned. Defaults to 0. */
  firstSeed?: number;
}

export interface ExampleSearch extends SeedSearch {
  /** Generator to sample from. Defaults to the default English generator. */
  generator?: WordSource;
  /** Options applied to every candidate. `seed` and `trace: true` are supplied. */
  options?: Omit<WordGenerationOptions, "seed" | "rand" | "trace">;
}

export interface Example {
  seed: number;
  /** The traced word that satisfied the predicate. */
  word: Word;
  /** Options that regenerate `word`; override `trace` to compare untraced output. */
  options: WordGenerationOptions & { seed: number; trace: true };
}

/**
 * Returns the first non-undefined result of `probe` over consecutive seeds.
 * Throws when none is found: the property became unreachable (or rarer than the
 * bound allows), which is a real signal rather than a seed to re-pick.
 */
export function searchSeeds<T>(search: SeedSearch, probe: (seed: number) => T | undefined): T {
  const firstSeed = search.firstSeed ?? 0;
  for (let seed = firstSeed; seed < firstSeed + search.limit; seed++) {
    const found = probe(seed);
    if (found !== undefined) return found;
  }
  throw new Error(
    `No example of ${search.property} within ${search.limit} words (seeds ${firstSeed}..${firstSeed + search.limit - 1}). `
    + "The behavior may have become unreachable or much rarer; investigate before raising the bound.",
  );
}

/** Finds the first traced word, by seed, that satisfies `predicate`. */
export function findExample(predicate: (word: Word) => boolean, search: ExampleSearch): Example {
  const generator = search.generator ?? { generateWord };
  return searchSeeds(search, seed => {
    const options = { ...search.options, seed, trace: true as const };
    const word = generator.generateWord(options);
    return predicate(word) ? { seed, word, options } : undefined;
  });
}

/**
 * The one place exact generated output is pinned.
 *
 * `src/core/golden-output.test.ts` compares a fresh capture with the committed
 * fixture; `npm run golden:update` rewrites the fixture. Any change to RNG
 * consumption or weighting is expected to change it: review the diff and
 * regenerate deliberately.
 *
 * Not part of the published build (excluded in tsconfig.json).
 */
import { createSeededRng, generateWords } from "../index.js";
import type { GenerationMode } from "../types.js";

export const GOLDEN_FIXTURE_URL = new URL("../core/golden-output.json", import.meta.url);
export const GOLDEN_UPDATE_COMMAND = "npm run golden:update";
export const GOLDEN_WORDS_PER_CASE = 40;

export interface GoldenCase {
  name: string;
  seed: number;
  mode: GenerationMode;
  morphology: boolean;
}

export const GOLDEN_CASES: readonly GoldenCase[] = [
  { name: "text, morphology", seed: 1, mode: "text", morphology: true },
  { name: "text, bare", seed: 2, mode: "text", morphology: false },
  { name: "lexicon, morphology", seed: 3, mode: "lexicon", morphology: true },
  { name: "lexicon, bare", seed: 4, mode: "lexicon", morphology: false },
];

export interface GoldenWord {
  clean: string;
  hyphenated: string;
  pronunciation: string;
}

export interface GoldenCaseOutput extends GoldenCase {
  /** RNG draws consumed by the whole batch. */
  rngDraws: number;
  words: GoldenWord[];
}

export interface GoldenOutput {
  regenerate: string;
  wordsPerCase: number;
  cases: GoldenCaseOutput[];
}

function captureCase(golden: GoldenCase): GoldenCaseOutput {
  const stream = createSeededRng(golden.seed);
  let rngDraws = 0;
  const rand = () => { rngDraws++; return stream(); };
  const words = generateWords(GOLDEN_WORDS_PER_CASE, { rand, mode: golden.mode, morphology: golden.morphology })
    .map(({ written, pronunciation }) => ({ clean: written.clean, hyphenated: written.hyphenated, pronunciation }));
  return { ...golden, rngDraws, words };
}

export function captureGoldenOutput(): GoldenOutput {
  return { regenerate: GOLDEN_UPDATE_COMMAND, wordsPerCase: GOLDEN_WORDS_PER_CASE, cases: GOLDEN_CASES.map(captureCase) };
}

/** JSON with one word per line, so fixture diffs read word by word. */
export function serializeGoldenOutput(output: GoldenOutput): string {
  const cases = output.cases.map(({ words, ...golden }) => {
    const header = JSON.stringify(golden).slice(1, -1);
    const lines = words.map(word => `        ${JSON.stringify(word)}`).join(",\n");
    return `    {${header},\n      "words": [\n${lines}\n      ]\n    }`;
  });
  return `{\n  "regenerate": ${JSON.stringify(output.regenerate)},\n  "wordsPerCase": ${output.wordsPerCase},\n  "cases": [\n${cases.join(",\n")}\n  ]\n}\n`;
}

// Test oracle for src/core/spelling-budget.test.ts: the pre-#331 quadratic
// budget scan and the enumerated measurement cases it is compared on.
import type { WrittenFormConstraints } from "../config/language.js";
import type { SpellingBudgetKey, SpellingBudgetMeasurement, SpellingBudgetValues } from "../core/spelling-coverage-types.js";
import { isConsonantToken, tokenizeGraphemes } from "../core/spelling-budget.js";
import { isVowelChar, isConsonantLetter } from "../utils/letters.js";

/** The original scan: re-joins the token list for every token's right context. */
export function referenceSpellingBudgets(surface: string, constraints: WrittenFormConstraints | undefined): SpellingBudgetMeasurement {
  const values: SpellingBudgetValues = { consonantGraphemes: 0, consonantLetters: 0, finalConsonantLetters: 0, vowelLetters: 0 };
  let consonants = 0;
  let vowels = 0;
  for (let i = 0; i < surface.length; i++) {
    consonants = isConsonantLetter(surface[i], i, surface) ? consonants + 1 : 0;
    vowels = isVowelChar(surface[i], i, surface) ? vowels + 1 : 0;
    values.consonantLetters = Math.max(values.consonantLetters, consonants);
    values.vowelLetters = Math.max(values.vowelLetters, vowels);
  }
  values.finalConsonantLetters = consonants;
  const tokens = tokenizeGraphemes(surface, constraints?.consonantGraphemes);
  let tokenRun = 0;
  for (let i = 0; i < tokens.length; i++) {
    tokenRun = isConsonantToken(tokens[i], i, tokens) ? tokenRun + 1 : 0;
    values.consonantGraphemes = Math.max(values.consonantGraphemes, tokenRun);
  }
  const limits: Partial<SpellingBudgetValues> = {};
  const configured: Array<[SpellingBudgetKey, number | undefined]> = [
    ["consonantGraphemes", constraints?.maxConsonantGraphemes],
    ["consonantLetters", constraints?.maxConsonantLetters],
    ["finalConsonantLetters", constraints?.maxFinalConsonantLetters],
    ["vowelLetters", constraints?.maxVowelLetters],
  ];
  for (const [key, value] of configured) if (value) limits[key] = value;
  return { values, limits, exceeded: configured.filter(([key, limit]) => !!limit && values[key] > limit).map(([key]) => key) };
}


export interface MeasurementCase {
  label: string;
  surface: string;
  constraints: WrittenFormConstraints | undefined;
}

export const alphabet = ["a", "A", "y", "Y", "t", "h", "b", "!", "\uD83D", "\uDE00"];
export const tokenLists: Array<string[] | undefined> = [
  undefined, [], ["th", "t"], ["t", "th"], ["ya", "y"], ["y", "ya"],
  ["Th", "TH", "th"], ["a", "yh", "!"], ["\uD83D\uDE00", "\uD83D"], ["\uD83D", "\uD83D\uDE00"],
];
export const limitKeys = ["maxConsonantGraphemes", "maxConsonantLetters", "maxFinalConsonantLetters", "maxVowelLetters"] as const;
export const limitValues = [undefined, 0, -1, Number.NaN, Number.POSITIVE_INFINITY, 1];
export const witnesses = ["", "strengths", "twelfths", "tchyath", "ThYATH", "yay", "\uD83D\uDE00ya", "Y", "aya", "bth", "y!", "\uD83D\uDE00y"];

function allLimits(value: number | undefined): WrittenFormConstraints {
  return { maxConsonantGraphemes: value, maxConsonantLetters: value, maxFinalConsonantLetters: value, maxVowelLetters: value };
}

/** Enumerate by code-unit length, preserving the preregistered alphabet order. */
export function* measurementCases(): Generator<MeasurementCase> {
  const gridConstraints: Array<WrittenFormConstraints | undefined> = [undefined, {}];
  for (const consonantGraphemes of tokenLists) {
    gridConstraints.push({ ...allLimits(1), consonantGraphemes });
    gridConstraints.push({ maxConsonantGraphemes: 3, maxConsonantLetters: 4, maxFinalConsonantLetters: 3, maxVowelLetters: 2, consonantGraphemes });
  }
  let level = [""];
  for (let length = 0; length <= 4; length++) {
    for (const surface of level) for (const [index, constraints] of gridConstraints.entries()) {
      yield { label: `grid/${length}/${index}`, surface, constraints };
    }
    if (length < 4) level = level.flatMap(prefix => alphabet.map(unit => prefix + unit));
  }
  for (const [listIndex, consonantGraphemes] of tokenLists.entries()) {
    for (const [valueIndex, value] of limitValues.entries()) {
      const limits = [...limitKeys.map(key => ({ [key]: value })), allLimits(value)];
      for (const [limitIndex, configured] of limits.entries()) for (const surface of witnesses) {
        yield { label: `limits/${listIndex}/${valueIndex}/${limitIndex}`, surface, constraints: { ...configured, consonantGraphemes } };
      }
    }
  }
}

import type { BaseSpelling } from "./core/base-spelling.js";
import { RNG } from "./utils/random";
import type { NuclearQuantity } from "./core/syllable-weight.js";
import type { WordTrace, OrthographySource } from "./core/trace";
import type { TraceCollector } from "./core/trace";

/**
 * Generation mode controlling syllable-count distribution and letter-length targeting.
 *
 * - `"text"` — simulates natural running text (heavy monosyllable bias).
 * - `"lexicon"` — simulates a dictionary/lexicon (balanced syllable distribution).
 */
export type GenerationMode = "text" | "lexicon";
export type MorphologyTemplate = "bare" | "suffixed" | "prefixed" | "both";

/** Literal segment positions within a generated base word, before affix assembly. */
export interface NucleusWordPositionWeights {
  initial: number;
  medial: number;
  final: number;
}

/**
 * A single phoneme (minimal sound unit) in the generator's inventory.
 *
 * Each phoneme carries articulatory metadata and positional weightings that
 * control how likely it is to appear in onsets, codas, nuclei, and at word
 * boundaries.
 */
export interface Phoneme {
  /** IPA symbol or ASCII representation of the sound (e.g. `"p"`, `"ʃ"`). */
  sound: string;

  /**
   * Whether the vocal cords vibrate when producing this sound.
   *
   * @example `true` for /z/ ("buzz"), `false` for /s/ ("hiss").
   */
  voiced: boolean;

  /**
   * Whether the phoneme is aspirated — produced with a small burst of air
   * (e.g. /pʰ/ in "pat").
   */
  aspirated?: boolean;

  /**
   * How the airflow is manipulated to produce the sound.
   *
   * Examples:
   * - `"stop"` — airflow completely blocked then released (e.g. /p/, /t/).
   * - `"nasal"` — air flows through the nose (e.g. /m/, /n/).
   * - `"fricative"` — air forced through a narrow space (e.g. /f/, /s/).
   *
   * Future language support (not used in English):
   * tap/flap, trill, ejective/implosive stops, clicks,
   * lateral fricatives/affricates, pharyngeal/uvular/epiglottal fricatives/stops.
   */
  mannerOfArticulation:
    | "highVowel"           // Vowels: high (close)
    | "midVowel"            // Vowels: mid
    | "lowVowel"            // Vowels: low (open)
    | "glide"               // Approximants, semivowels (e.g. /j/, /w/)
    | "liquid"              // Lateral approximants and rhotics (e.g. /l/, /r/)
    | "nasal"               // Nasal stops (e.g. /m/, /n/, /ŋ/)
    | "fricative"           // Voiced or voiceless (e.g. /f/, /v/, /θ/)
    | "affricate"           // e.g. /tʃ/, /dʒ/
    | "stop"                // Plosives (e.g. /p/, /t/, /k/)
    | "sibilant"            // High-pitched fricatives (e.g. /s/, /ʃ/)
    | "lateralApproximant"; // Laterals without complete closure (e.g. /l/)

  /**
   * Where in the vocal tract the sound is produced.
   *
   * Examples:
   * - `"bilabial"` — both lips (e.g. /p/, /b/).
   * - `"alveolar"` — tongue against the alveolar ridge (e.g. /t/, /d/).
   * - `"velar"` — back of tongue against the soft palate (e.g. /k/, /g/).
   *
   * Future language support (not used in English):
   * retroflex, labial-palatal, pharyngeal,
   * epiglottal, uvular, alveolo-palatal.
   */
  placeOfArticulation:
    | "front"             // Vowel: front
    | "central"           // Vowel: central
    | "back"              // Vowel: back
    | "bilabial"          // Both lips (e.g. /p/, /b/)
    | "labiodental"       // Lip and teeth (e.g. /f/, /v/)
    | "dental"            // Tongue against teeth (e.g. /θ/, /ð/)
    | "alveolar"          // Tongue against alveolar ridge (e.g. /t/, /d/)
    | "postalveolar"      // Behind alveolar ridge (e.g. /ʃ/, /ʒ/)
    | "palatal"           // Tongue against hard palate (e.g. /j/)
    | "velar"             // Tongue against soft palate (e.g. /k/, /g/)
    | "glottal"           // Using the glottis (e.g. /h/)
    | "labial-velar";     // Simultaneous bilabial + velar (e.g. /w/)

  /** Weighting for appearing in a syllable nucleus (vowel position). */
  nucleus?: number;
  /** Weighting for appearing in a syllable onset (initial consonant cluster). */
  onset?: number;
  /** Weighting for appearing in a syllable coda (final consonant cluster). */
  coda?: number;
  /** Legacy tense classification used by existing sonority, reduction and spelling rules; not quantity or duration. */
  tense?: boolean;
  /** Explicit phonological quantity under a named analysis. Missing means unspecified. */
  nuclearQuantity?: NuclearQuantity;

  /** Whether this vowel was reduced (e.g. schwa substitution in unstressed syllables). */
  reduced?: boolean;

  /** Legacy first-syllable weighting for onset/nucleus selection. */
  startWord: number;
  /** Legacy weighting when the applicable first/last-syllable flag is absent. */
  midWord: number;
  /** Legacy last-syllable weighting for coda/nucleus selection. */
  endWord: number;

  /**
   * Explicit segment-position weights for this phoneme when used as a nucleus.
   * Overrides startWord/midWord/endWord for nuclei only; consonant clusters retain
   * their legacy semantics. An isolated segment must pass both edge restrictions.
   */
  nucleusWordPosition?: NucleusWordPositionWeights;
}

/** Type-safe accessor for a phoneme's positional weight (onset / nucleus / coda). */
export function getPhonemePositionWeight(p: Phoneme, position: "onset" | "nucleus" | "coda"): number | undefined {
  switch (position) {
  case "onset": return p.onset;
  case "nucleus": return p.nucleus;
  case "coda": return p.coda;
  }
}

/**
 * Context condition for a grapheme — restricts when a spelling is valid
 * based on surrounding phonemes and word position.
 */
export interface GraphemeCondition {
  /**
   * Optional language-config alias for reusable condition presets.
   * Resolved from LanguageConfig.graphemeConditionAliases before evaluation.
   */
  alias?: string;
  /** Previous phoneme's sound must be in this list (or match a category shorthand). */
  leftContext?: string[];
  /** Next phoneme's sound must be in this list (or match a category shorthand). */
  rightContext?: string[];
  /** Previous phoneme's sound must NOT be in this list. */
  notLeftContext?: string[];
  /** Next phoneme's sound must NOT be in this list. */
  notRightContext?: string[];
  /** Previous grapheme's last letter must be one of these (raw letters, not phoneme categories). */
  leftGraphemeContext?: string[];
  /** Previous grapheme's last letter must NOT be one of these. */
  notLeftGraphemeContext?: string[];
  /**
   * The written letter that directly follows this grapheme must NOT be one of
   * these. Only checked where that letter is already fixed when the grapheme is
   * chosen: at the end of a root, the first letter of its planned suffix.
   */
  notRightGraphemeContext?: string[];
  /**
   * `true`: the grapheme must end the written word, i.e. spell the base's last
   * segment with no planned suffix after it. `false`: it must not. Prefixes are
   * irrelevant.
   */
  wordFinal?: boolean;
  /** Literal segment positions; unlike wordPosition, these do not describe the containing syllable. */
  segmentPosition?: ("initial" | "medial" | "final")[];
  /** Legacy syllable-position restriction. Prefer segmentPosition for literal word edges. */
  wordPosition?: ("initial" | "medial" | "final")[];
  /**
   * Syllable-shape guard for the current syllable where this grapheme is applied.
   * Useful for constraints like bare nucleus spellings.
   */
  syllableShape?: {
    onset?: "empty" | "nonEmpty" | "any";
    coda?: "empty" | "nonEmpty" | "any";
    nucleusLength?: number | { min?: number; max?: number };
  };
}

/**
 * A grapheme — the written (spelling) representation of a phoneme.
 *
 * Each grapheme maps a phoneme sound to one of its possible written forms,
 * weighted by frequency and syllable position.
 */
/** Reading obligations are independent of selection eligibility and frequency. */
export type GraphemeReading =
  | { kind: "single-phone" }
  | { kind: "open-vowel-or-split-marker" }
  | { kind: "following-letter"; require?: string[]; forbid?: string[] }
  | { kind: "unsupported-construction"; reason: string };

export interface Grapheme {
  /** The IPA/ASCII phoneme sound this grapheme represents. */
  phoneme: string;
  /** The written letter(s) (e.g. `"sh"` for /ʃ/, `"ough"` for /oʊ/). */
  form: string;
  /**
   * Index into the ORIGINS array indicating the grapheme's etymological source.
   * 0 = Germanic, 1 = French, 2 = Greek, 3 = Latin, 4 = Other.
   * @see ORIGINS in `elements/graphemes`
   */
  origin: number;
  /** Baseline frequency weight (higher → more likely to be chosen). */
  frequency: number;

  /** Weighting modifier when used in a syllable onset. */
  onset?: number;
  /** Weighting modifier when used in a syllable coda. */
  coda?: number;
  /** Weighting modifier when used in a syllable nucleus. */
  nucleus?: number;
  /** Weighting modifier when used inside a consonant cluster. */
  cluster?: number;

  /** Initial position weight in positionScope; zero excludes the candidate. */
  startWord: number;
  /** Medial position weight in positionScope; zero excludes the candidate. */
  midWord: number;
  /** Final position weight in positionScope; zero excludes the candidate. */
  endWord: number;

  /** Scope of startWord/midWord/endWord. Omission retains legacy syllable scope. */
  positionScope?: "segment" | "syllable";
  /** Explicit weight for a syllable that is both first and last; zero forbids it. */
  isolatedSyllableWeight?: number;
  /** Consider only when the ordinary pool has no legal positive-weight spelling. */
  fallbackOnly?: boolean;

  /** Context condition restricting when this grapheme is valid. */
  condition?: GraphemeCondition;
  /** Omission leaves reading certification unavailable to phone-preserving repair. */
  reading?: GraphemeReading;
}

/**
 * The spelled (orthographic) representation of a generated word.
 */
export interface WrittenForm {
  /** The plain written form (e.g. `"brintle"`). */
  clean: string;
  /** The hyphenated form showing syllable breaks (e.g. `"brin-tle"`). */
  hyphenated: string;
}

/**
 * A fully generated word, including its phonological structure, pronunciation,
 * and written form.
 *
 * @example
 * ```ts
 * const word: Word = generateWord();
 * console.log(word.written.clean);  // "strandel"
 * console.log(word.pronunciation);  // IPA string
 * console.log(word.syllables.length); // 2
 * ```
 */
export interface Word {
  /** Lexical segments and stress before surface aspiration and vowel reduction. */
  lexical?: LexicalForm;
  /** Ordered array of syllables that make up the word. */
  syllables: Syllable[];
  /** IPA pronunciation string for the full word. */
  pronunciation: string;
  /** Written (spelled) forms of the word. */
  written: WrittenForm;
  /** Generation trace (only present when `trace: true` was passed). */
  trace?: WordTrace;
}

export interface LexicalForm {
  /**
   * Base-root syllables used for spelling, with the root's lexical stress. A
   * syllable whose vowel final stress repair replaced carries its final-word
   * stress instead, because that stress forced the repaired vowel.
   */
  root: Syllable[];
  /** Full derived word after morphology and final stress resolution. */
  syllables: Syllable[];
  /** Position of the first root syllable in the full lexical form. */
  rootSyllableStart: number;
}

/**
 * A single syllable, decomposed into onset, nucleus, and coda.
 *
 * @example
 * ```ts
 * // The syllable "stran" has:
 * //   onset:   [s, t, r]
 * //   nucleus: [a]
 * //   coda:    [n]
 * ```
 */
export interface Syllable {
  /** Initial consonant cluster (may be empty). */
  onset: Phoneme[];
  /** Vowel core of the syllable (typically one phoneme). */
  nucleus: Phoneme[];
  /** Final consonant cluster (may be empty). */
  coda: Phoneme[];
  /** Stress level: primary (`'ˈ'`), secondary (`'ˌ'`), or unstressed (`undefined`). */
  stress?: "ˈ" | "ˌ" | undefined;
}

/**
 * Options accepted by {@link generateWord}.
 */
export interface WordGenerationOptions {
  /** An existing partial word to continue building on. */
  word?: Word;
  /** Integer seed for deterministic generation. Same seed → same word. */
  seed?: number;
  /** Force the root to have exactly this many syllables (1–7). Affixes may add more. */
  syllableCount?: number;
  /**
   * Custom random-number generator. Takes priority over {@link seed} — when
   * both are provided the seed is silently ignored.
   *
   * Any `() => number` function returning values in [0, 1) is accepted.
   */
  rand?: RNG;
  /**
   * Generation mode controlling the root syllable-count distribution.
   * - `"text"` — monosyllable-heavy, mimics running text.
   * - `"lexicon"` (default) — balanced distribution, mimics a dictionary.
   */
  mode?: GenerationMode;
  /**
   * Whether to apply morphological affixation (prefixes/suffixes) to the
   * generated root word. Requires `morphology.enabled` in the language config.
   * Defaults to `true` when the active config enables morphology.
   */
  morphology?: boolean;
  /**
   * When `true`, attaches a detailed generation trace to `word.trace`.
   * Purely observational — does not affect generation behavior.
   */
  trace?: boolean;
}

/**
 * Internal context threaded through the generation pipeline.
 * @internal
 */
export interface WordGenerationContext {
  /** Live base-word spelling state; internal and independent of trace collection. */
  baseSpelling?: BaseSpelling;
  /** Per-word RNG instance — all randomness in the pipeline draws from this. */
  rand: RNG;
  /** The word being built. */
  word: Word;
  /** Target number of syllables. */
  syllableCount: number;
  /** Index of the syllable currently being generated. */
  currSyllableIndex: number;
  /** Target total phoneme count for top-down generation. */
  targetPhonemeCount?: number;
  /** Per-syllable onset/coda length targets for top-down generation. */
  syllablePlans?: SyllableShapePlan[];
  /** Trace collector (only present when tracing is enabled). */
  trace?: TraceCollector;
  /** Source domain of syllables passed to the orthographic writer. */
  orthographySource?: OrthographySource;
  /** Written text that will directly follow the spelled syllables (a planned suffix). */
  orthographyFollowing?: string;
}

/**
 * Planned shape for a generated syllable in top-down mode.
 *
 * Values represent consonant counts; each syllable always receives one nucleus
 * phoneme separately.
 */
export interface SyllableShapePlan {
  onsetLength: number;
  codaLength: number;
}

/**
 * Internal context for building a consonant/vowel cluster.
 * @internal
 */
export interface ClusterContext {
  /** Per-cluster RNG instance (inherited from the word context). */
  rand: RNG;
  /** Syllable position this cluster occupies. */
  position: "onset" | "coda" | "nucleus";
  /** Phonemes accumulated so far in this cluster. */
  cluster: Phoneme[];
  /** Cached sound strings parallel to cluster[] — avoids repeated .map(ph => ph.sound). */
  clusterSounds: string[];
  /** Phoneme sounds to exclude from candidate selection (Set for O(1) lookup). */
  ignoreSet: ReadonlySet<string>;
  /** Legacy first-syllable flag, set for onsets and nuclei. */
  isStartOfWord: boolean;
  /** Legacy last-syllable flag, set for codas and nuclei. */
  isEndOfWord: boolean;
  /** Provisional literal base-word edges for the nucleus segment being selected. */
  nucleusWordEdges?: { initial: boolean; final: boolean };
  /** Maximum phonemes allowed in this cluster. */
  maxLength: number;
  /** Total syllable count of the word being generated. */
  syllableCount: number;
  /** True when this onset follows a syllable with no coda. */
  followingOpenNucleus?: boolean;
  /** Sounds that may not open this onset, given the preceding open syllable's nucleus. */
  bannedFirstOnset?: ReadonlySet<string>;
  /**
   * Nucleus phonemes of the syllable being built (for nucleus-aware coda filtering).
   * Only populated when position === "coda".
   */
  nucleus?: Phoneme[];
}

import type { RNG } from "./random.js";

/**
 * Returns a weighted random option, given an array of options with weights.
 * ```
 * let color = getWeightedOption([
 *   ["red", 10],
 *   ["green", 30],
 *   ["blue", 50],
 * ], rand);
 * ```
 * Courtesy Mark Knol, T: @mknol (sourced from: https://github.com/liamegan/fxhash-helpers/blob/main/src/index.js)
 * @param options - options in the format of [ [ string: optionName, int: optionNumber ] ]
 * @param rand - RNG function returning a value in [0, 1).
 */
const getWeightedOption = <T>(options: [T, number][], rand: RNG): T => {
  if (options.length === 0) {
    throw new Error("getWeightedOption requires at least one option");
  }
  let totalWeight = 0;
  for (let i = 0; i < options.length; i++) totalWeight += options[i][1];
  const randomValue = rand() * totalWeight;

  let cumulativeWeight = 0;
  for (let i = 0; i < options.length; i++) {
    cumulativeWeight += options[i][1];
    if (randomValue < cumulativeWeight) {
      return options[i][0];
    }
  }

  // Fallback to last option (should rarely happen due to floating-point precision)
  return options[options.length - 1][0];
};

export default getWeightedOption;

export const VOWEL_LETTERS = new Set(["a", "e", "i", "o", "u", "y"]);

/**
 * Check if a character is a vowel letter.
 * Y is consonantal when followed by a vowel (a,e,i,o,u), e.g. "yet", "yawn".
 * Otherwise, including at the end of a word, Y is a vowel.
 */
export function isVowelChar(ch: string, idx: number, str: string): boolean {
  const lower = ch.toLowerCase();
  if (lower === "y") {
    // Y followed by a vowel letter (a,e,i,o,u) is consonantal (e.g. "yet", "yoga", "beyond")
    // Y in all other positions is a vowel (e.g. "gym", "fly", "myth")
    const next = idx + 1 < str.length ? str[idx + 1].toLowerCase() : "";
    return next === "" || !"aeiou".includes(next);
  }
  return VOWEL_LETTERS.has(lower);
}

export function isConsonantLetter(ch: string, idx?: number, str?: string): boolean {
  if (idx !== undefined && str !== undefined) {
    return !isVowelChar(ch, idx, str);
  }
  return !VOWEL_LETTERS.has(ch.toLowerCase());
}

import { Phoneme } from "../types.js";

const OBSTRUENT_MANNERS = new Set([
  "stop", "fricative", "affricate", "sibilant",
]);

export function isObstruent(p: Phoneme): boolean {
  return OBSTRUENT_MANNERS.has(p.mannerOfArticulation);
}

export function isNasal(p: Phoneme): boolean {
  return p.mannerOfArticulation === "nasal";
}

export function isStop(p: Phoneme): boolean {
  return p.mannerOfArticulation === "stop";
}

/**
 * A random-number generator function that returns a value in [0, 1).
 */
export type RNG = () => number;

/**
 * Create a deterministic RNG seeded with a 32-bit integer (Mulberry32).
 *
 * Excellent distribution, 4-line core, 32-bit state. Replaces the old
 * `Math.sin()` hack used in `createSeededRandom`.
 *
 * @param seed - Integer seed value.
 * @returns A deterministic {@link RNG}.
 */
export function createSeededRng(seed: number): RNG {
  let t = seed | 0;
  return () => {
    t = (t + 0x6d2b79f5) | 0;
    let r = Math.imul(t ^ (t >>> 15), 1 | t);
    r = (r + Math.imul(r ^ (r >>> 7), 61 | r)) ^ r;
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Create a non-deterministic RNG backed by `Math.random()`.
 *
 * @returns An {@link RNG} that delegates to `Math.random()`.
 */
export function createDefaultRng(): RNG {
  return () => Math.random();
}

// ---------------------------------------------------------------------------
// Internal RNG implementations
// ---------------------------------------------------------------------------

import unglish from './index';

// Explicitly assign unglish to self (which is the global scope in a worker)
self.unglish = unglish;

